            'mailboxes' => 'Почтовые ящики подключают FreeITSM к учётным записям электронной почты, чтобы входящие сообщения становились заявками, а ответы уходили обратно — добавьте и аутентифицируйте те, которые отслеживает ваша служба поддержки.',
            'privacy' => 'Заявка хранит не только вашу переписку с тем, кто её создал. Пересылка поставщику или копия коллеге помещает это сообщение в ту же заявку — и их ответ тоже попадает туда. Здесь определяется, какую часть этого видит заявитель на портале самообслуживания.',
            'indexing' => 'Текст внутри вложений читается, чтобы по нему можно было искать. Файлы Word, Excel, PowerPoint и обычные текстовые файлы FreeITSM читает сам, в момент их поступления. PDF, старые файлы Office и сканированные документы требуют отдельной службы чтения документов — настройте её в разделе <strong>System &rarr; Integrations &rarr; Apache Tika</strong> — и поскольку это занимает гораздо больше времени, они читаются в фоне. Эти два переключателя определяют, когда выполняется эта фоновая работа.',
            'merge_behaviour' => 'Когда две заявки оказываются одним и тем же, аналитик может их объединить. Эти настройки определяют, как это влияет на номера заявок, которые есть у ваших заявителей, и что происходит с перепиской. Они действуют для всех — объединение меняет то, что видит клиент, поэтому два аналитика на одном почтовом ящике не должны расходиться во мнениях.',
            'reply_templates' => 'Готовые ответы, которые аналитики могут вставить в ответ вместо повторного набора. Это общие шаблоны, которые видит вся команда — личные шаблоны аналитика сохраняются из окна ответа и здесь не перечислены.',
            'rota_shifts' => 'Смены — это шаблоны рабочего графика (например, ранняя, поздняя, дежурство), которые назначаются аналитикам в графике персонала — определите их здесь, прежде чем составлять график.',
            'analysts' => 'Аналитики — это сотрудники, которые входят в систему и работают с заявками — добавляйте их, сбрасывайте пароли и назначайте в команды, чтобы управлять их доступом.',
            'general' => 'Общие настройки определяют поведение заявок — повторное открытие, отложенные заявки и то, как долго показываются сообщения и переписки.',
            'statuses' => 'Состояния рабочего процесса, в которых может находиться заявка. Статусы с отметкой <em>Закрыто</em> считаются конечными — их используют отчёты, счётчики Watchtower и автоматическая установка даты закрытия при назначении. Ровно один статус является статусом по умолчанию для новых заявок.',
            'priorities' => 'Уровни приоритета, отображаемые в заявках. Ровно один приоритет является приоритетом по умолчанию для новых заявок.',
            'rota_locations' => 'Где каждый аналитик работает в данный день — используется в графике персонала и отображается цветной меткой в каждой записи. Ровно одно место является местом по умолчанию для новых записей графика.',
            'email_templates' => 'Автоматические ответы по электронной почте, запускаемые событиями заявок. Используется только первый активный шаблон для каждого события.',
