            'col_default' => 'По умолчанию',
            'col_actions' => 'Действия',
            'notifs_heading' => 'Уведомления о нарушении',
            'notifs_info' => '<strong style="display:block;margin-bottom:6px;font-size:14px;">Как работают правила уведомлений</strong>У каждого правила четыре части: <strong>область</strong>, <strong>триггер</strong>, <strong>цель</strong> и список <strong>получателей</strong>.<br><br><strong>Область</strong> бывает <em>По умолчанию</em> (правило действует для заявок всех отделов) или <em>конкретный отдел</em> (правило действует только для заявок этого отдела).<br>При проверке заявки система сначала ищет правило для её отдела &mdash; если оно есть, действует оно, а правило по умолчанию игнорируется. Если правила для отдела нет, используется правило по умолчанию. Так можно задать разумные настройки для всех отделов, а затем сделать исключения там, где у команды другие требования к эскалации.<br><br><strong>Триггер</strong> &mdash; это либо <em>Предупреждение</em> (заявка перешла порог предупреждения &mdash; возможное нарушение близко), либо <em>Нарушение</em> (заявка превысила цель SLA &mdash; нарушение произошло). Каждый из них &mdash; отдельное правило, поэтому о предупреждениях и нарушениях можно уведомлять разных людей.<br><br><strong>Цель</strong> &mdash; какой отсчёт SLA отслеживать: <em>Реакция</em>, <em>Решение</em> или <em>Оба</em>.<br><br><strong>Получатели</strong> &mdash; любое сочетание: текущий исполнитель заявки, все аналитики команд отдела заявки, один выбранный аналитик и (или) список произвольных адресов эл. почты (удобно для общих ящиков или почтовых мостов в Slack/Teams).<br><br><strong style="color:var(--warning-text, #92400e);">Нет правил &mdash; нет писем.</strong> Даже если заявка нарушила SLA, ничего не отправится, пока вы не добавите хотя бы одно правило (начните с пары «Предупреждение + Нарушение» в области «По умолчанию», чтобы охватить всё).',
            'notifs_dedup' => 'Каждая заявка вызывает не более одного письма на цель и триггер &mdash; cron-обработчик запоминает, что уже отправлено, поэтому дубликатов не будет.',
