            'existing_note' => '<strong>Уже присвоенные номера не меняются.</strong> У существующих заявок остаются их номера, и все номера, когда-либо выданные FreeITSM, продолжают работать &mdash; в том числе в ответах на старые письма. Если нужно перенумеровать и существующие заявки, ниже есть инструмент. <strong>Цифры не закончатся:</strong> выбранная ширина — это минимум, поэтому заявка 1 000 001 просто получит на цифру больше, ничего не сломается.',
            'saved' => 'Нумерация заявок сохранена.',
            'renumber_heading' => 'Перенумеровать существующие заявки',
            'renumber_intro' => 'Переписывает номер каждой существующей заявки по схеме выше, начиная с самых старых. Полезно главным образом сразу после перехода с другой системы, когда нужно привести всё к единому виду.',
            'renumber_safety' => '<strong>Старые номера продолжают работать.</strong> Каждый номер, который когда-либо был у заявки, запоминается, поэтому ответ на письмо со старым номером попадёт в нужную заявку &mdash; так же, как при объединении заявок. Выведенный из употребления номер также никогда не присваивается другой заявке. Однако это нельзя отменить, поэтому сначала посмотрите предпросмотр.',
            'renumber_preview' => 'Предпросмотр',
            'renumber_go' => 'Перенумеровать',
