            'renumber_preview_heading' => 'Только предпросмотр &mdash; ничего не изменено.',
            'renumber_done_heading' => 'Заявки перенумерованы.',
            'renumber_summary' => 'Будет перенумеровано заявок: {changing} из {total}. Уже совпадают: {skipped}.',
            'renumber_next_after' => 'Следующая новая заявка получит номер {number}.',
            'renumber_confirm_title' => 'Перенумеровать все заявки?',
            'renumber_confirm' => 'Номер каждой существующей заявки будет переписан.

Старые номера продолжают работать, поэтому ответы на старые письма по-прежнему находят нужную заявку. Но номера, которые люди записали, указали в бланках и сохранили в собственных таблицах, больше не будут совпадать с теми, что показывает FreeITSM.

Это нельзя отменить. Продолжить?',
