            'system_name_moved_link' => 'Система -> Брендинг',
            'system_name_placeholder' => 'напр. Система учёта заявок службы поддержки',
            'system_name_help' => 'Показывается в начале заголовка каждой страницы - название на вкладке браузера и в закладках. Если пусто, используется «Service Desk».',
            'reopen_label' => 'Повторное открытие',
