            'flag_duplicates_help' => 'Повторная отправка, дубликат доставки или отказ с исходным письмом сворачиваются с пометкой, какому сообщению они соответствуют. Ничего не удаляется.',
            'ai_heading' => 'Вспомогательные функции чтения с ИИ',
            'ai_desc' => 'Необязательно и выключено, пока вы не включите: в отличие от всего остального на этой странице, здесь используется ваш собственный ИИ-провайдер, и каждое обращение платное. Провайдер, модель и API key настраиваются один раз на вкладке «Очистка ответов». Ничто из написанного ИИ не заменяет заявку — переписка остаётся на месте целиком.',
