            'ai_max_label' => 'Сообщений для чтения',
            'ai_max_help' => 'Насколько далеко назад читает сводка. Более длинная заявка читается с последнего конца, и сводка прямо об этом говорит, а не описывает начало, которого не видела.',
            'ai_notes_label' => 'Разрешить читать внутренние примечания',
