            'ai_confidential_block' => 'Никогда не отправлять их в ИИ (рекомендуется)',
            'ai_confidential_allow' => 'Обращаться как с любой другой заявкой',
            'ai_confidential_help' => 'Относится ко всем функциям ИИ, которые читают заявку: сводка, «Прочитать», очистка ответа, «Спросить ИИ», сводки объединения, статьи для базы знаний, сводки каналов, анализ проблем и бот комнаты кризисного управления. Конфиденциальная заявка либо не отправляется, либо — когда одновременно читается много заявок — исключается или показывается только по номеру.',
            'ai_read_help' => 'Кнопка, которая читает всю заявку и кратко рассказывает о ней: что произошло, что не решено и что она сделала бы дальше. Запрашивается и читается один раз, нигде не сохраняется.',
