        'hero_title' => 'Руководство по модулю «Заявки»',
        'hero_sub' => 'Регистрируйте, отслеживайте и решайте обращения в ИТ-поддержку в едином почтовом ящике с папками &mdash; создано для команд службы поддержки.',
