            'tips' => 'Быстрые советы',
            'companies' => 'Компании',
        ],
        'overview' => [
            'heading' => 'Обзор',
            'intro' => 'Модуль «Заявки» &mdash; ядро вашей ИТ-службы поддержки. Он предлагает привычный интерфейс в стиле почтового клиента для работы с обращениями, инцидентами и сервисными задачами. Заявки поступают от конечных пользователей по электронной почте или создаются вручную, а аналитики обрабатывают их с помощью папок, приоритетов и таймеров SLA &mdash; всё необходимое для быстрой ИТ-поддержки.',
            'card_inbox_title' => 'Входящие',
            'card_inbox_body' => 'Входящие с папками, построенные по образцу почтового клиента. Просматривайте папки «Мои заявки», «Не назначено», «Все открытые» и «Закрытые». Нажмите на любую заявку, чтобы открыть панель чтения с подробностями, историей и действиями.',
            'card_dashboard_title' => 'Панель',
            'card_dashboard_body' => 'Создайте персональную панель с настраиваемыми виджетами Chart.js. Визуализируйте количество заявок, время отклика, разбивку по категориям и нагрузку аналитиков с помощью столбчатых, круговых, кольцевых и линейных диаграмм.',
            'card_calendar_title' => 'Календарь',
            'card_calendar_body' => 'Просматривайте заявки в календарной сетке по датам создания, срока или решения. Быстро замечайте просроченные дела и планируйте неделю, видя общую картину заявок с первого взгляда.',
            'card_rota_title' => 'График',
            'card_rota_body' => 'Планируйте смены аналитиков и графики дежурств. Видите, кто доступен в любое время, планируйте покрытие на выходные и праздники и следите, чтобы ни одна заявка не осталась без внимания.',
        ],
        'inbox' => [
            'heading' => 'Входящие',
            'intro' => 'Входящие &mdash; основное рабочее место аналитиков. Используется трёхпанельная раскладка &mdash; папки слева, список заявок по центру и панель чтения справа &mdash; так что сортировать и отвечать можно, не покидая страницу.',
            'p_live' => '<strong>Страница обновляется сама.</strong> Каждую минуту входящие проверяют ваши почтовые ящики и ищут новое в заявках, которые вам видны &mdash; письмо, полученное в фоне, сообщение в WhatsApp, Telegram, Slack, Teams или Mattermost, ответ коллеги &mdash; и если что-то пришло, список и счётчики папок обновляются сами, как при нажатии кнопки обновления. Заявка, которую вы читаете, и ответ, который вы набираете, остаются нетронутыми.',
            'p_folders' => 'Панель папок группирует заявки логически. У каждой папки есть счётчик непрочитанных, поэтому новая работа заметна сразу:',
            'field_my' => '<strong>Мои заявки</strong> &mdash; заявки, назначенные вам. Это ваша личная очередь и лучшее место, с которого стоит начинать день.',
            'field_unassigned' => '<strong>Не назначено</strong> &mdash; заявки, которые поступили, но у которых ещё нет аналитика. Берите их отсюда, чтобы взять ответственность на себя.',
            'field_all_open' => '<strong>Все открытые</strong> &mdash; все заявки, которые ещё не закрыты, независимо от владельца. Удобно руководителям и лидерам команд, следящим за общим объёмом.',
            'field_closed' => '<strong>Закрытые</strong> &mdash; решённые заявки. Ищите здесь, когда нужно сослаться на прошлое решение или вновь открыть проблему.',
            'field_dept' => '<strong>Папки отделов</strong> &mdash; заявки, сгруппированные по отделам (например, ИТ, HR, Финансы). Отделы настраиваются в разделе «Настройки» и автоматически появляются как вложенные папки.',
            'switch_heading' => '<strong>Переключение между группировкой по отделам и по аналитикам</strong>',
            'switch_body' => 'Небольшой переключатель из двух кнопок вверху панели папок переключает между двумя представлениями одних и тех же данных. Группировка <strong>Отдел</strong> (по умолчанию) показывает заявки под каждым отделом с вложенными папками статусов; группировка <strong>Аналитик</strong> переворачивает её, и каждая папка верхнего уровня представляет личную очередь аналитика с вложенными папками статусов. Папка <strong>Не назначено</strong> зависит от контекста &mdash; в режиме отделов в ней заявки без отдела, в режиме аналитиков &mdash; заявки без исполнителя, так что всегда видно, что нужно взять в работу. Ваш выбор сохраняется для каждого аналитика, поэтому каждый участник команды сохраняет привычное представление между сеансами.',
            'p_actions' => 'Над списком заявок расположены четыре кнопки: <strong>Создать</strong> для создания заявки, <strong>Поиск</strong> для поиска заявок по ключевому слову, номеру или заявителю, <strong>Фильтр</strong> для сужения видимого и <strong>Обновить</strong> для перезагрузки текущей папки.',
            'filter_body' => 'Кнопка <strong>Фильтр</strong> (воронка) сужает папки и список одновременно, как бы они ни были сгруппированы. <strong>Мои</strong> показывает только заявки, назначенные вам, а <strong>Скрыть закрытые</strong> убирает все заявки, статус которых помечен как закрытый. Пока фильтр включён, на воронке появляется точка, а рядом с заголовком списка — подпись, так что вы всегда знаете, что видите не всё. Если папки сгруппированы по <strong>аналитикам</strong>, ваша собственная папка вместо этого располагается вверху как <strong>Мои заявки</strong>. У поиска есть собственный переключатель <strong>Включая закрытые заявки</strong>, по умолчанию включённый, потому что поиск обычно нужен для старой заявки. Оба выбора сохраняются только для вас.',
            'row_name' => 'Каждая строка показывает номер заявки, а затем имя. По умолчанию это <strong>человек, создавший заявку</strong>, и оно не меняется всё время жизни заявки. Если вы предпочитаете видеть автора последнего сообщения &mdash; им станет ваш почтовый ящик, как только вы ответите &mdash; измените <strong>Имя рядом с номером заявки</strong> в разделе <strong>Настройки &rarr; Отображение строк</strong>, где также можно скрыть имя и оставить только номер. Эта вкладка &mdash; ваша личная настройка: она ничего не меняет для остальных.',
            'tip' => 'Нажмите на любую заявку в списке, чтобы загрузить её в панель чтения. Оттуда можно изменять поля, добавлять комментарии, отвечать по почте или прикреплять файлы &mdash; не покидая входящие.',
        ],
        'faster' => [
            'heading' => 'Работа быстрее',
            'intro' => 'Четыре приёма, которые превращают напряжённое утро в управляемое: готовые ответы, действия сразу над многими заявками и размещение переписки там, где ей место.',
            'templates_heading' => 'Готовые ответы',
            'templates_body' => 'Вы постоянно отправляете одни и те же ответы. Напишите ответ один раз, затем нажмите <strong>Шаблоны</strong> слева внизу окна ответа, чтобы вставить его в позицию курсора &mdash; он добавляется к набранному, а не заменяет его. Шаблоны &mdash; форматированный текст, поддерживающий те же заполнители <code>[merge_code]</code>, что и автоматические письма, поэтому <code>[requester_first_name]</code> заменяется настоящим именем при вставке.',
            'templates_team' => '<strong>Шаблоны команды</strong> &mdash; доступны всем, настраиваются в разделе «Настройки &rarr; Шаблоны ответов».',
            'templates_mine' => '<strong>Ваши собственные</strong> &mdash; сохраните черновик через <em>Сохранить черновик как шаблон</em>. Виден только вам, разрешение не требуется.',
            'templates_tip' => 'Называйте шаблон по ситуации («Принтер не в сети &mdash; первые шаги»), а не по формулировке. Именно её вы будете искать в девять утра.',
            'select_heading' => 'Выбор нескольких заявок',
            'select_body' => 'Список заявок работает как Outlook или Проводник. Без флажков.',
            'key_click' => 'Щелчок',
            'key_click_d' => 'выбрать одну и открыть её',
            'key_ctrl' => 'Ctrl+щелчок',
            'key_ctrl_d' => 'добавить или убрать одну, не затрагивая остальные',
            'key_shift' => 'Shift+щелчок',
            'key_shift_d' => 'выбрать целый блок от последнего щелчка',
            'key_kb' => 'Клавиатура',
            'key_kb_d' => 'стрелки для перемещения, Shift+стрелки для расширения выбора, Ctrl+стрелки и пробел для выбора разрозненных заявок, Ctrl+A для всех, Escape для сброса',
            'select_actions' => 'Когда выбрано несколько заявок, <strong>щёлкните любую из них правой кнопкой</strong>, чтобы разом задать статус, приоритет, отдел, тип или исполнителя для всех &mdash; или перетащите весь набор на папку. Что показывает экран при выборе нескольких заявок &mdash; на ваше усмотрение, в меню учётной записи в разделе «Предпочтения».',
            'select_tip' => 'Щелчок правой кнопкой по заявке, которой <em>нет</em> в выборе, сбрасывает выбор и применяется только к ней. Это сделано намеренно &mdash; вы никогда не подействуете на набор, от которого уже отошли.',
            'merge_heading' => 'Объединение дубликатов',
            'merge_body' => 'Двое сообщили об одном сбое? Выберите заявки, щёлкните правой кнопкой, <strong>Объединить</strong>. Переписки собираются вместе, а если настроен ИИ-провайдер, FreeITSM пишет краткую сводку того, о чём просили все и что уже сделано, чтобы взявшемуся за заявку не приходилось читать четыре цепочки.',
            'merge_tip' => 'Ничего не удаляется. Присоединённая заявка сохраняет свой номер, остаётся доступной для поиска, показывает, куда она переехала &mdash; а клиент, отвечающий на старое письмо о ней, всё равно дойдёт до вас.',
            'split_heading' => 'Разделение заявки',
            'split_body' => 'Обратная задача. Когда кто-то посреди переписки поднимает вторую, не связанную тему, нажмите <strong>Разделить</strong> у этого сообщения (или щёлкните правой кнопкой по заголовку сообщения). Оно переносится в новую заявку, при желании вместе со всеми более новыми сообщениями, а в исходной остаётся метка, показывающая, куда они ушли.',
            'split_tip' => 'Дайте новой заявке нормальную тему. По умолчанию подставляется тема перенесённого сообщения, а это обычно «RE:» по <em>старой</em> проблеме.',
            'undo_heading' => 'Передумали',
            'undo_body' => 'Оба действия можно отменить через баннер в заявке. Отмена <strong>разделения</strong> отклоняется, если кто-то уже ответил в новой заявке, добавил примечание или записал время &mdash; вам точно скажут, что мешает. Отмена <strong>объединения</strong> возвращает заявке её сообщения, примечания и записанное время и вновь открывает её в прежнем виде, но ответы, написанные в другой заявке после объединения, остаются там.',
        ],
        'working' => [
            'heading' => 'Работа с заявками',
            'intro' => 'Каждое обращение проходит жизненный цикл: оно создаётся, сортируется, обрабатывается и в итоге решается. Модуль «Заявки» даёт инструменты для эффективной работы на каждом этапе, от первичной регистрации до закрытия.',
            'creating_heading' => '<strong>Создание новой заявки</strong>',
            'step1' => '<strong>Нажмите «Создать»</strong> &mdash; откройте окно новой заявки на панели инструментов входящих. Укажите имя и адрес электронной почты заявителя, чтобы он получал обновления.',
            'step2' => '<strong>Задайте тему</strong> &mdash; напишите чёткое, краткое описание проблемы. Оно отображается в списке заявок и во всех уведомлениях, отправляемых конечному пользователю.',
            'step3' => '<strong>Выберите отдел, тип и приоритет</strong> &mdash; выберите подходящий отдел, тип заявки (например, инцидент, запрос на обслуживание) и уровень приоритета. Эти поля управляют таймерами SLA и правилами маршрутизации.',
            'step4' => '<strong>Добавьте описание</strong> &mdash; изложите все подробности проблемы в редакторе форматированного текста. Укажите шаги воспроизведения, сообщения об ошибках и любой контекст, который понадобится решающему аналитику.',
            'step5' => '<strong>Сохраните</strong> &mdash; заявка создаётся с уникальным номером и появляется в подходящей папке. Отсчёт SLA начинается сразу, исходя из приоритета.',
            'editing_heading' => '<strong>Редактирование заявок и управление ими</strong>',
            'editing_body' => 'Когда заявка создана, любое поле можно изменить в панели чтения. Основные поля:',
            'card_status_title' => 'Статус',
            'card_status_body' => 'Отслеживайте жизненный цикл заявки: Новая, Открыта, В работе, Ожидание, Решена, Закрыта',
            'card_priority_title' => 'Приоритет',
            'card_priority_body' => 'Задайте срочность и влияние: Критический, Высокий, Средний, Низкий. У каждого уровня своя цель SLA',
            'card_category_title' => 'Категория',
            'card_category_body' => 'Классифицируйте тип проблемы: оборудование, ПО, сеть, доступ, общее. Полезно для отчётности',
            'card_analyst_title' => 'Назначенный аналитик',
            'card_analyst_body' => 'Человек, отвечающий за решение заявки. Переназначение записывается в журнал активности',
            'card_enduser_title' => 'Конечный пользователь',
            'card_enduser_body' => 'Человек, создавший обращение. Найдите по имени или почте, чтобы связать с существующей записью пользователя',
            'card_dept_title' => 'Отдел',
            'card_dept_body' => 'Направляйте заявки в нужную команду. Отделы определяют группировку папок и фильтры панели',
            'flow_new' => 'Новая',
            'flow_in_progress' => 'В работе',
            'flow_resolved' => 'Решена',
            'flow_closed' => 'Закрыта',
            'triage_heading' => '<strong>Сортировка перетаскиванием</strong>',
            'triage_body' => 'Чтобы рассортировать заявку, её не обязательно открывать. Перетащите любую строку списка на папку, чтобы изменить поля одним движением:',
            'triage_dept' => '<strong>Представление по отделам</strong> &mdash; перетащите на папку отдела для переназначения, на вложенную папку статуса под отделом, чтобы обновить оба значения сразу, на <strong>Не назначено</strong>, чтобы сбросить отдел.',
            'triage_analyst' => '<strong>Представление по аналитикам</strong> &mdash; перетащите на папку аналитика, чтобы назначить его владельцем (задаются и <code>assigned_analyst_id</code>, и <code>owner_id</code>, поэтому поле «Владелец» в панели чтения остаётся согласованным), на вложенную папку статуса, чтобы обновить оба значения, на <strong>Не назначено</strong>, чтобы сбросить исполнителя.',
            'triage_spring' => '<strong>Папки, раскрывающиеся при наведении</strong> &mdash; задержите заявку над свёрнутой папкой во время перетаскивания, и она раскроется сама (как в Outlook), так что любой вложенный статус доступен без предварительного сброса.',
            'fullscreen_heading' => '<strong>Полноэкранный режим</strong>',
            'fullscreen_body' => 'Когда нужно сосредоточиться на одной заявке &mdash; длинная переписка, сложное изменение, подробный ответ &mdash; переключитесь в полноэкранный режим. Список папок и список заявок исчезают, переписка занимает всю доступную ширину, а свойства (отдел, тип, статус, источник, решено с первого раза, обучение ИТ, владелец) переходят в вертикальную боковую панель справа.',
            'fullscreen_max' => '<strong>Значок развёртывания</strong> &mdash; небольшой значок в правом конце строки темы заявки. Нажмите, чтобы войти в полноэкранный режим; нажмите ещё раз, чтобы вернуться к трёхпанельной раскладке.',
            'fullscreen_dbl' => '<strong>Двойной щелчок по строке</strong> &mdash; дважды щёлкните любую заявку в списке, чтобы сразу открыть её на весь экран, как жест «действительно открыть эту» в Outlook.',
            'fullscreen_sticks' => '<strong>Сохраняется при смене заявки</strong> &mdash; войдя в полноэкранный режим, вы остаётесь в нём при переходе к следующей заявке. Перезагрузка страницы (F5) без выбранной заявки возвращает стандартную трёхколоночную раскладку, так что вы не застрянете со скрытым списком папок.',
            'rightclick_heading' => '<strong>Быстрые действия правой кнопкой</strong>',
            'rightclick_body' => 'Щёлкните правой кнопкой любую заявку в списке, чтобы открыть контекстное меню. Вверху меню показан номер заявки, чтобы вы знали, с чем работаете, и каждое действие применяется к заявке, по которой вы щёлкнули, <em>не меняя</em> то, что сейчас открыто в панели чтения &mdash; удобно, когда вы читаете заявку А и нужно рассортировать заявку Б, не теряя места.',
            'rightclick_status' => '<strong>Задать статус &rarr;</strong> &mdash; выпадающее подменю со всеми активными статусами и их цветовыми метками. Рядом с текущим значением стоит галочка, если вы щёлкнули по открытой заявке. Выбор сразу обновляет заявку, записывает запись в журнал аудита, обновляет счётчики папок и при необходимости синхронизирует выпадающий список статуса в панели чтения.',
            'rightclick_priority' => '<strong>Задать приоритет &rarr;</strong> &mdash; тот же принцип подменю, источник &mdash; справочник активных приоритетов, цвет каждого показан меткой. Первая строка &mdash; вариант <em>(без приоритета)</em> для сброса значения (приоритет может быть пустым).',
            'rightclick_assign' => '<strong>Назначить &rarr;</strong> &mdash; подменю со всеми загруженными аналитиками и серой плашкой с инициалами, плюс строка <em>(не назначено)</em> сверху для сброса. Выбор задаёт и <code>assigned_analyst_id</code>, и <code>owner_id</code>, поэтому поле «Владелец» в панели чтения остаётся согласованным.',
            'rightclick_cmdb' => '<strong>Связать объект CMDB&hellip;</strong> &mdash; открывает выбор с поиском по мере ввода. Нажмите на результат, чтобы связать его, и продолжайте &mdash; поле очищается и снова получает фокус для следующего, а журнал «Недавно связанные» в окне показывает накопленный список с зелёными галочками подтверждений.',
            'rightclick_time' => '<strong>Записать время&hellip;</strong> &mdash; открывает окно с минутами, выбором даты и времени (по умолчанию «сейчас», так что можно записать и задним числом) и необязательным полем примечаний.',
            'rightclick_phone' => '<strong>На телефоне</strong> нажмите и удерживайте заявку полсекунды, чтобы открыть то же меню в виде полноэкранной панели. Пункт с дополнительными вариантами &mdash; «Задать статус», «Задать приоритет», «Назначить» &mdash; сдвигается к ним, а кнопка <strong>Назад</strong> возвращает обратно.',
            'rightclick_tip' => 'Если заявка, с которой вы работаете через контекстное меню, оказывается той же, что открыта в панели чтения, соответствующий раздел там (выпадающие списки статуса и приоритета, объекты CMDB, записи времени) обновляется автоматически при закрытии окна, так что интерфейс остаётся согласованным.',
            'time_heading' => '<strong>Учёт времени</strong>',
            'time_body' => 'Время, потраченное на заявку, записывается в отдельный раздел <strong>Записи времени</strong> в панели чтения, между панелью связанных объектов CMDB и панелью примечаний. В заголовке показан общий итог (например, «Всего 2ч 30м»), а каждая запись ниже показывает затраченное время, аналитика, дату и все добавленные примечания.',
            'time_step1' => '<strong>Встроенная форма</strong> &mdash; введите потраченные минуты в числовое поле, при желании краткое описание в поле примечаний и нажмите <strong>Добавить</strong>. Новая запись сразу появляется вверху списка с вашим именем и текущей отметкой времени.',
            'time_step2' => '<strong>Запись задним числом через правую кнопку</strong> &mdash; если нужно внести время, которое вы забыли записать раньше, щёлкните заявку в списке правой кнопкой и выберите <strong>Записать время&hellip;</strong>. В окне есть выбор даты и времени, чтобы поставить на запись фактическое время выполнения работы.',
            'time_step3' => '<strong>Удаление своих записей</strong> &mdash; рядом с записями, которые внесли вы, появляется небольшая кнопка &times;. Нажмите её (и подтвердите) для мягкого удаления &mdash; строка остаётся в базе данных с <code>is_active = 0</code> для аудита, но исчезает из списка. Записи других аналитиков удалить нельзя.',
            'time_tip1' => 'Время хранится в обычных минутах (45 мин, 90 мин и т. д.), а в интерфейсе отображается как <code>45м</code> или <code>1ч 30м</code> &mdash; достаточно точно для коротких исправлений и без мучений с округлением десятичных часов.',
            'time_tip2' => 'Каждое изменение поля записывается в журнал активности заявки. Всегда можно увидеть, кто что и когда изменил, что необходимо для соответствия требованиям аудита и передачи дел между аналитиками.',
        ],
        'comments' => [
            'heading' => 'Комментарии и вложения',
            'intro' => 'Журнал активности &mdash; сердце каждой заявки. Он фиксирует каждое действие &mdash; комментарии, изменения полей, отправленные письма и прикреплённые файлы &mdash; в хронологической ленте, рассказывающей всю историю обращения.',
            'adding_heading' => '<strong>Добавление комментариев</strong>',
            'step1' => '<strong>Откройте заявку</strong> &mdash; нажмите на любую заявку во входящих, чтобы загрузить панель чтения. Прокрутите вниз, чтобы увидеть весь журнал активности и поле комментария внизу.',
            'step2' => '<strong>Напишите заметку</strong> &mdash; кнопкой «Добавить заметку» откройте редактор комментария. По умолчанию заметки внутренние и видны только аналитикам службы поддержки.',
            'step3' => '<strong>Ответьте или перешлите по почте</strong> &mdash; действиями «Ответить» или «Переслать» отправьте сообщение конечному пользователю или третьей стороне. Письмо записывается в журнал активности вместе с содержимым исходящего сообщения.',
            'files_heading' => '<strong>Вложенные файлы</strong>',
            'files_body' => 'Прикрепляйте к заявке снимки экрана, журналы, документы и любые подтверждающие файлы. Файлы можно перетащить в область вложений или выбрать через обзор файлов. Вложения хранятся на сервере и связаны с журналом активности заявки, так что ничто не теряется.',
            'audit_heading' => '<strong>Журналирование аудита</strong>',
            'audit_body' => 'Журнал активности автоматически записывает каждое действие без участия аналитика. Когда приоритет меняется со среднего на высокий, фиксируются старое и новое значения. Когда заявка переназначается, записываются и прежний, и новый аналитик. Так создаётся полная неизменяемая история, отвечающая требованиям аудита ITIL и помогающая руководителям понять, как обрабатываются заявки.',
            'tip' => 'При ответе по почте можно добавить получателей копии (Cc) и прикрепить файлы за одно действие. Вся почтовая переписка попадает в журнал активности заявки, и вся коммуникация остаётся в одном месте.',
        ],
        'ai' => [
            'heading' => 'Инструменты ИИ',
            'intro' => 'В рабочий процесс заявки встроены две функции на основе Claude: <strong>Очистка ответа</strong> превращает черновик в грамотно оформленное письмо, а <strong>Спросить ИИ</strong> ищет в базе знаний на естественном языке с учётом контекста заявки.',
            'cleanup_heading' => '<strong>Очистка ответа &mdash; кнопка ✨ в редакторе ответа</strong>',
            'cleanup_body' => 'Набросайте в ответе черновик (или просто тезисы вроде *«нужно перезапустить службу печати, сделать для них снимок экрана»*) и нажмите кнопку <strong>✨ Очистить</strong>. Claude перепишет текст как грамотно оформленное письмо &mdash; добавит приветствие <em>Уважаемый(ая) [имя],</em> по заявителю, исправит грамматику, применит заданный тон и завершит словами <em>С уважением,</em>. Запрос настроен так, что ИИ НЕ будет выдумывать технические детали, придумывать извинения или раздувать текст сверх написанного вами.',
            'cleanup_streams' => '<strong>Потоковый вывод</strong> &mdash; переписанный текст появляется в редакторе по мере генерации Claude (не нужно ждать перед индикатором загрузки).',
            'cleanup_undo' => '<strong>Ссылка «Отменить» на 30 с</strong> &mdash; если Claude испортит текст, под редактором на 30 секунд после завершения переписывания появится небольшая ссылка <em>Отменить</em>, возвращающая исходный черновик.',
            'cleanup_tone' => '<strong>По тону</strong> &mdash; три готовых тона настраиваются в разделе <strong>Настройки &rarr; Очистка ответа</strong>: <em>Дружелюбный</em> (по умолчанию), <em>Официальный</em>, <em>Краткий</em>. Выберите тот, что соответствует стилю вашей команды.',
            'cleanup_key' => '<strong>Собственный ключ API</strong> &mdash; отдельный ключ Anthropic, не совпадающий с ключами ИИ-функций RFP, базы знаний и рабочих процессов, поэтому расход отображается отдельной строкой в биллинге Anthropic. Настраивается в разделе <strong>Настройки &rarr; Очистка ответа</strong>.',
            'cleanup_tip' => 'Очистка лучше всего подходит для рутинных ответов вроде «я попробовал это, пожалуйста, попробуйте X». Длинные, тонкие сообщения лучше писать самостоятельно &mdash; ИИ отлично справляется со структурой, но не знает вашей конкретной среды.',
            'ask_heading' => '<strong>Спросить ИИ &mdash; кнопка 🤖 на панели инструментов заявки</strong>',
            'ask_body' => 'Нажмите кнопку <strong>Спросить ИИ</strong> (🤖) на панели инструментов заявки, чтобы открыть выдвижную панель чата, знающую тему, текст и контекст панели чтения открытой заявки. Задавайте вопросы вроде *«мы уже сталкивались с этим?»* или *«как обычно исправляют эту ошибку?»*, и она семантически ищет в базе <a href="../knowledge/" style="color:#0078d4;">знаний</a> (через Claude и эмбеддинги OpenAI) и отвечает подходящими статьями с прямыми ссылками для открытия.',
            'ask_context' => '<strong>Учёт контекста</strong> &mdash; панель знает, какую заявку вы смотрите, поэтому можно задавать общие вопросы, а она сама определит нужный контекст.',
            'ask_linked' => '<strong>Связанные статьи</strong> &mdash; предложения кликабельны и открывают подходящую статью базы знаний в новой вкладке.',
            'ask_shared' => '<strong>Общий доступ с модулем «База знаний»</strong> &mdash; ИИ использует тот же ключ и модель, что и ИИ-поиск по базе знаний, поэтому однократная настройка даёт обе функции. Подробности настройки см. в справке модуля «База знаний».',
        ],
        'csat' => [
            'heading' => 'Опросы удовлетворённости клиентов (CSAT)',
            'intro' => 'Отправляйте заявителю по эл. почте опрос с оценкой от 1 до 5, когда заявка решена, собирайте ответ на странице без входа в систему и отслеживайте тенденции по каждому аналитику на отдельной странице аналитики.',
            'modes_heading' => '<strong>Два режима запуска &mdash; выберите один</strong>',
            'mode_auto' => '<strong>Автоматически при закрытии</strong> &mdash; опрос ставится в очередь автоматически, когда заявка переходит в любой закрытый статус. Аналитику ничего делать не нужно &mdash; опрос запускается решением заявки.',
            'mode_manual' => '<strong>Только вручную</strong> &mdash; аналитик нажимает кнопку ⭐ <strong>Обратная связь</strong> на панели инструментов заявки, когда хочет спросить. Удобно, если вы предпочитаете решать для каждой заявки отдельно, запрашивать ли отзыв.',
            'mode_off' => '<strong>Выкл.</strong> &mdash; функция отключена; письма с опросами не отправляются.',
            'modes_choose' => 'Выбор находится в разделе <strong>Заявки &rarr; Настройки &rarr; CSAT</strong>. Кнопка ручного запуска работает и в <em>автоматическом</em> режиме &mdash; при необходимости аналитики могут повторно запросить отзыв по заявке, по которой опрос уже отправлялся.',
            'template_heading' => '<strong>Шаблон письма</strong>',
            'template_body' => 'Текст письма с опросом берётся из существующей вкладки <strong>Шаблоны писем</strong> &mdash; создайте шаблон с событием <strong>Опрос CSAT</strong> (новое событие рядом с <em>Заявка назначена</em> / <em>Заявка закрыта</em>) и вставьте код подстановки <code>[csat_link]</code> там, где должна появиться ссылка на оценку. Стандартные коды подстановки (<code>[requester_name]</code>, <code>[ticket_reference]</code>, <code>[analyst_name]</code>) доступны как обычно.',
            'template_tip' => 'Если активного шаблона CSAT нет, кнопка <em>Обратная связь</em> откажет с понятной ошибкой, а автоматический запуск тихо пропустит отправку &mdash; нерабочих ссылок на опрос не возникнет никогда.',
            'survey_heading' => '<strong>Страница опроса</strong>',
            'survey_body' => 'Заявитель нажимает ссылку в письме и попадает на страницу без входа в систему с выбором оценки от 1 до 5 и необязательным полем для комментария. Два визуальных стиля настраиваются в разделе <strong>Настройки &rarr; CSAT</strong>:',
            'survey_stars' => '<strong>Звёзды</strong> &mdash; классическое заполнение при наведении. Если навести на звезду №3, золотом заполняются №1, №2 и №3. Нажмите, чтобы зафиксировать.',
            'survey_emojis' => '<strong>Эмодзи</strong> &mdash; 5 лиц 😡 🙁 😐 🙂 😀 сначала серые, с прозрачностью 40%; лицо под курсором или выбранное возвращает полный цвет и увеличивается в 1,25&times; раза. Нажмите, чтобы зафиксировать.',
            'survey_store' => 'Оба режима сохраняют одно и то же число от 1 до 5, поэтому дашборды и средние значения работают одинаково, какой бы стиль ни использовался. Ссылка на опрос одноразовая &mdash; после отправки ответа та же ссылка повторную отправку не принимает.',
            'chat_heading' => '<strong>Опрос клиентов чата прямо в чате</strong>',
            'chat_body' => 'Если отмечено <strong>Спрашивать клиентов чата в их чате</strong>, клиента, который написал в WhatsApp, Telegram, Slack, Microsoft Teams или Mattermost, спрашивают в этом же чате, а не по эл. почте &mdash; пять кнопок в Telegram, Teams и Mattermost и &ldquo;ответьте одной цифрой&rdquo; в остальных. Ответ попадает в те же результаты, что и ответ на опрос по почте.',
            'chat_rules' => 'В WhatsApp вопрос задаётся, только пока открыто 24-часовое окно для ответа; вне его, а также если сообщение в чат отправить не удалось, используется опрос по эл. почте. Цифра считается оценкой, только если она идёт сразу после вопроса &mdash; в том же чате, в течение недели и до того, как клиент написал что-либо ещё &mdash; поэтому &ldquo;3&rdquo; в ответ на вопрос аналитика остаётся обычным сообщением. После обновления выключено; для новой установки включено.',
            'analytics_heading' => '<strong>Страница аналитики</strong>',
            'analytics_body' => 'Нажмите кнопку ⭐ <strong>CSAT</strong> в навигации (между «График» и «Настройки»), чтобы открыть панель аналитики по адресу <code>tickets/csat/</code>. Период можно выбрать: 7 / 30 / 90 / 365 дней.',
            'card_kpi_title' => 'Плитки KPI',
            'card_kpi_body' => 'Средняя оценка (из 5), число ответов, доля ответивших (ответили ÷ отправлено)',
            'card_dist_title' => 'Распределение оценок',
            'card_dist_body' => 'Столбчатая диаграмма оценок от 1 до 5 с точным числом и процентами',
            'card_leader_title' => 'Рейтинг аналитиков',
            'card_leader_body' => 'Средняя оценка и число ответов по каждому аналитику, по убыванию средней. Используйте для бесед о развитии',
            'card_recent_title' => 'Последние ответы',
            'card_recent_body' => 'Оценки от новых к старым, по 25 на странице, с комментариями в свободной форме и клиентом, который их оставил, со ссылкой на исходную заявку',
            'analytics_filters' => 'Сузить страницу можно фильтрами под заголовком: диапазон дат <strong>С / По</strong> (вместо кнопок дней), группа <strong>Оценка</strong> (Положительные 4-5, Нейтральные 3, Отрицательные 1-2), <strong>Аналитик</strong> и <strong>Клиент</strong>. Аналитик и клиент сужают все показатели на странице; группа оценок сужает только список ответов, чтобы среднее по-прежнему имело смысл. На телефоне фильтры скрыты за кнопкой <strong>Фильтры</strong> внизу экрана. Страницу с фильтрами можно добавить в закладки.',
            'analytics_company' => 'Все показатели следуют за <strong>переключателем компании</strong> в заголовке: выбранная вами компания или все доступные вам компании при выборе <strong>Все компании</strong>.',
            'analytics_tip' => 'Привязка к аналитику сохраняется при переназначении заявки, потому что идентификатор аналитика записывается в строку опроса в момент отправки, а не определяется заново. Если заявку передавали из рук в руки до закрытия, оценка принадлежит аналитику, который её фактически закрыл.',
            'one_heading' => '<strong>Один опрос на заявку</strong>',
            'one_body' => 'Если включено <em>Один опрос на заявку</em> (по умолчанию), то по заявке, которую открыли заново и снова закрыли, новый опрос отправляется, только если аналитик запустит его вручную &mdash; это защищает от спама опросами по проблемной заявке, которая постоянно меняет статус. Выключите, если хотите, чтобы каждое закрытие запускало новый опрос.',
        ],
        'users' => [
            'heading' => 'Управление пользователями',
            'intro' => 'Кнопка <strong>Пользователи</strong> в навигации открывает <code>tickets/users.php</code> &mdash; каталог всех конечных пользователей (людей, которые создают заявки, а не аналитиков) вместе с историей заявок каждого.',
            'p_intro' => 'Пользователи попадают в систему четырьмя реактивными способами &mdash; самостоятельная регистрация на портале, входящее письмо от нового отправителя, опрос почтового ящика или создание движком рабочих процессов по сработавшей заявке. Этого хватает в большинстве случаев, но на странице «Пользователи» можно также <strong>заранее создать</strong> пользователя (например, нового сотрудника, которому скоро понадобится доступ) и <strong>изменить</strong> или <strong>удалить</strong> существующие записи.',
            'add_heading' => '<strong>Добавление пользователя</strong>',
            'add_body' => 'Кнопка <strong>Добавить</strong> в заголовке списка пользователей открывает редактор человека. Это тот же редактор, что открывается из раздела <strong>Активы &rarr; Пользователи</strong>, поэтому человека добавляют и изменяют одинаково на любом экране:',
            'add_email' => '<strong>Эл. почта</strong> &mdash; необязательно, потому что у людей, входящих через каталог, может не быть почтового ящика; их находят по имени для входа. Укажите адрес эл. почты или отображаемое имя. Адрес должен быть уникальным и не должен принадлежать аналитику.',
            'add_names' => '<strong>Отображаемое имя / предпочитаемое имя</strong> &mdash; необязательно. Предпочитаемое имя используется в обращении к пользователю в письмах (например, <em>«Саша»</em> вместо <em>«Александр Петров»</em>).',
            'add_password' => '<strong>Пароль</strong> &mdash; необязательно. Если оставить поле пустым, создаётся учётная запись <em>без пароля</em> &mdash; ровно в том же состоянии, в котором начинают пользователи из входящих заявок. Позже пользователь может сам завладеть учётной записью через регистрацию на портале самообслуживания, задав собственный пароль.',
            'add_details' => '<strong>Должность, отдел, офис, телефон, мобильный, табельный номер и менеджер</strong> &mdash; всё необязательно, и всё описывает <em>человека</em>, а не учётную запись. Стоит заполнить: <strong>офис</strong> подскажет, на какой площадке находится человек, прежде чем вы начнёте его искать, <strong>менеджер</strong> фиксирует линию подчинения (начните вводить часть имени, чтобы найти его), а <strong>табельный номер</strong> служит ключом сопоставления при сверке с платёжной системой, которая никогда не слышала об адресах эл. почты. При импорте из каталога всё это приходит заполненным. Адресная книга CardDAV заполняет всё, кроме табельного номера и менеджера: в карточке контакта для них нет места.',
            'managed_heading' => '<strong>Люди, данные которых ведутся в другом месте</strong>',
            'source_body' => '<strong>Откуда взят человек</strong>, указано в его данных (<em>Данные из: Contoso AD - каталог</em>), а фильтр <strong>Источник</strong> под полем поиска показывает только людей из одного каталога или адресной книги либо только добавленных в FreeITSM, с числом рядом с каждым. Он появляется, как только кто-либо привязан к источнику.',
            'add_book_body' => '<strong>Добавить в адресную книгу.</strong> Тот, кто написал письмо, существует здесь, но не числится ни в одной адресной книге. Если администратор включил <em>Разрешить аналитикам добавлять людей в эту адресную книгу</em> (Система &rarr; Аутентификация, в настройках адресной книги), то у такого человека рядом с «Изменить» появляется кнопка <strong>Добавить в адресную книгу</strong>. Сначала она спрашивает подтверждение и показывает, что попадёт в карточку, затем создаёт контакт и связывает его с человеком &mdash; это тот же человек, а не копия. Она не добавит того, чей адрес эл. почты в книге уже есть (запустите импорт), и следит, чтобы следующий импорт подхватил новый контакт, иначе убирает карточку обратно.',
            'managed_body' => 'Если человек был импортирован &mdash; из LDAP или Active Directory либо из адресной книги CardDAV, &mdash; данные, которыми владеет источник, доступны <strong>только для чтения</strong>, и в окне они затемнены. Источник, откуда они пришли, является основным, и следующий импорт перезаписал бы всё, что введено здесь, поэтому сохранение отклоняется сразу, а не принимается и не откатывается незаметно через час. <strong>Какие</strong> данные, зависит от источника: каталог владеет всеми семью, а адресная книга &mdash; пятью: ей негде хранить табельный номер и линию подчинения, поэтому эти два поля остаются за вами. А если в адресной книге включено <em>записывать изменения обратно</em>, не заблокировано ничего: то, что вы вводите, отправляется в карточку контакта, и следующему импорту нечего откатывать. Всё остальное в записи, включая компанию и пароль, всегда можно изменить.',
            'edit_heading' => '<strong>Изменение пользователя</strong>',
            'edit_body' => 'Выберите пользователя в списке и нажмите <strong>Изменить</strong> в заголовке сведений. Тот же редактор, уже заполненный. Сохранение без пароля оставляет прежний хеш нетронутым; ввод пароля сбрасывает его. Если менеджер человека работает в компании, которую вы не видите, поле «Менеджер» сообщает об этом, и менеджер остаётся прежним, пока вы не выберете другого.',
            'signin_body' => '<strong>Входит через</strong> показывает, с каким провайдером единого входа связан человек. Кнопка <strong>Отвязать</strong> рядом с ним после подтверждения удаляет эту связь, и следующий вход начнётся с нуля &mdash; для тех, кто перешёл к другому провайдеру или был связан не с той учётной записью. Для людей, которых ведёт синхронизация каталога, кнопка не предлагается: она просто связала бы их снова.',
            'company_body' => '<strong>Компания</strong> появляется, если их у вас больше одной. У нового человека пустое значение означает, что компания определяется по его адресу эл. почты; у существующего пустое значение означает отсутствие компании, и его заявки попадают в сортировку.',
            'managers_heading' => '<strong>Менеджеры</strong>',
            'managers_body' => 'Человека можно назначить <strong>менеджером</strong> на портале самообслуживания: у него появляется вкладка <strong>Заявки команды</strong> со списком заявок тех, кем он руководит. Она выключена, пока администратор не включит её в разделе <strong>Система &rarr; Менеджеры</strong>; там же решается, могут ли менеджеры отвечать на эти заявки или закрывать их и что они видят в конфиденциальной заявке (по умолчанию ничего).',
            'managers_sources' => 'Менеджером можно быть двумя способами, и оба действуют одновременно: человек указан в поле <strong>Менеджер</strong> в записях других людей (вручную или из вашего каталога), и для него настроены <strong>линии управления</strong>. Нажмите <strong>Доступ менеджера</strong> рядом с «Изменить», чтобы открыть для этого человека полноэкранную страницу, где можно дать ему всех, отдельных людей, группы людей, отделы или всю его линию подчинения, а также <strong>исключить</strong> людей &mdash; исключение всегда главнее, в том числе поля «Менеджер». Страница показывает, скольких людей он может видеть, и перечисляет их, рассчитывая так, будто менеджеры уже включены, чтобы вы могли проверить всё до включения. Нажмите на любого человека в этом списке, чтобы узнать, <strong>почему</strong> менеджер его видит и как это прекратить.',
            'managers_rules' => 'Менеджер видит только людей из своей компании, никогда себя и вообще никого после увольнения. Отделы сопоставляются по названию, введённому у каждого человека, поэтому переименованный отдел перестаёт совпадать &mdash; страница и раздел «Система &rarr; Менеджеры» предупреждают о строке отдела, которой не соответствует никто. По умолчанию линии управления могут менять только администраторы; в разделе «Система &rarr; Менеджеры» это можно открыть для всех, кто вправе изменять людей.',
            'delete_heading' => '<strong>Удаление пользователя</strong>',
            'delete_body' => 'Кнопка <strong>Удалить</strong> <strong>безопасна для внешних ключей</strong>: она откажет, если пользователь является заявителем по каким-либо заявкам или имеет строки в <code>users_assets</code>, и вернёт понятное сообщение <em>«Невозможно удалить: этот пользователь является заявителем по N заявкам. Сначала переназначьте или закройте эти заявки.»</em> История аудита никогда не нарушится незаметно.',
            'tip' => 'Во всех полях окна отключено автозаполнение браузера (включая <code>autocomplete="new-password"</code> в поле пароля), чтобы сохранённые учётные данные самого аналитика не подставлялись в форму, единственная цель которой — создание записи <em>другого человека</em>.',
            'groups_heading' => '<strong>Группы</strong>',
            'groups_body' => 'Вкладка <strong>Группы</strong> рядом с <strong>Люди</strong> содержит именованные группы людей &mdash; аналитики и пользователи портала самообслуживания вместе в одной группе. Группа создаётся один раз здесь и затем используется во всём FreeITSM, так что вы можете дать ей доступ к папке базы знаний или назначить ей учебный курс, не составляя один и тот же список дважды.',
            'groups_make' => '<strong>Создайте группу</strong> кнопкой <strong>Добавить</strong> на вкладке «Группы»: укажите название и описание, которое стоит заполнить, потому что следующему человеку нужно понимать, для чего эта группа.',
            'groups_add' => '<strong>Добавляйте людей</strong> через поиск &mdash; он находит аналитиков и пользователей портала вместе, так что не нужно знать, к какому типу относится человек.',
            'groups_expiry' => '<strong>Задайте членству дату окончания</strong>, если доступ временный. Трое инженеров, работающих на площадке две недели, добавляются с последним днём и выходят из группы сами, когда он наступает. Истёкшее членство остаётся в списке с пометкой об истечении, поэтому вы по-прежнему видите, у кого был доступ и до какого времени.',
            'groups_uses' => '<strong>Для чего нужна группа:</strong> для выдачи доступа к папке базы знаний и для назначения обучения в LMS сразу набору людей. Изменения членства вступают в силу немедленно &mdash; потом ничего применять заново не нужно.',
            'groups_admin' => '<strong>Группы видит любой, у кого есть модуль «Заявки»; изменять их может только администратор.</strong> Добавление человека в группу может дать ему и доступ к закрытой папке базы знаний, поэтому это выдача доступа, а не просто раскладка по папкам.',
        ],
        'dash' => [
            'heading' => 'Панель',
            'intro' => 'Панель заявок даёт наглядную аналитику с настраиваемыми виджетами Chart.js. У каждого аналитика своя раскладка панели, так что можно сосредоточиться на показателях, важных для вашей роли &mdash; будь то личная загрузка, пропускная способность команды или соблюдение SLA.',
            'step1' => '<strong>Откройте библиотеку</strong> &mdash; нажмите «Редактировать панель», чтобы перейти в режим редактирования, затем просмотрите библиотеку виджетов. Выберите готовые виджеты или создайте свой, выбрав тип диаграммы и свойство данных для агрегирования.',
            'step2' => '<strong>Добавьте виджеты</strong> &mdash; нажмите кнопку + на любом виджете в библиотеке, чтобы добавить его на панель. Он появится сразу и начнёт показывать актуальные данные из вашей базы заявок.',
            'step3' => '<strong>Настройте</strong> &mdash; нажмите значок шестерёнки на любом виджете, чтобы изменить его название, тип диаграммы (столбчатая, круговая, кольцевая, линейная, столбчатая с накоплением, многолинейная), фильтр по диапазону дат, фильтр по отделу и группировку по времени (по дням, неделям, месяцам).',
            'step4' => '<strong>Расположите</strong> &mdash; перетаскивайте виджеты, чтобы изменить их порядок. Раскладка сохраняется для каждого аналитика и остаётся между сеансами.',
            'examples' => 'Типичные примеры виджетов: <strong>Заявки по статусам</strong> (кольцевая диаграмма: открытые, решённые и закрытые), <strong>Заявки по приоритетам</strong> (столбчатая диаграмма объёма по степени серьёзности), <strong>Недельный объём</strong> (линейная диаграмма новых заявок во времени) и <strong>Нагрузка аналитиков</strong> (столбчатая с накоплением: активные заявки каждого аналитика).',
            'tip' => 'Используйте фильтры по диапазону дат на отдельных виджетах, чтобы сравнивать текущие показатели с прошлыми периодами. Например, вид «Этот месяц и прошлый месяц» помогает заранее заметить тенденции в объёме заявок.',
        ],
        'cal_rota' => [
            'heading' => 'Календарь и график',
            'intro' => 'Два инструмента планирования помогают команде сохранять порядок: календарь заявок, наглядно показывающий нагрузку во времени, и график сотрудников для управления сменами и доступностью на дежурстве.',
            'cal_heading' => '<strong>Календарь</strong>',
            'cal_body' => 'Календарь отображает каждую запланированную вами заявку &mdash; через <strong>Запланировать работу</strong>, что есть в самой заявке и в контекстном меню входящих, &mdash; цветным блоком в запланированное время, нарисованным на её <strong>реальную длительность</strong>, а не на фиксированный час. Красные блоки &mdash; приоритет <em>Высокий</em>, зелёные &mdash; <em>Низкий</em>, синие &mdash; всё остальное. Для навигации используйте <em>Сегодня</em>, стрелки <em>&lt;</em> / <em>&gt;</em> и переключатель <strong>Месяц / Неделя / День</strong>.',
            'cal_scope' => '<strong>Мои или Все.</strong> Календарь открывается на вашей запланированной работе, а рядом с кнопками режимов есть переключатель <strong>Все</strong>; ваш выбор запоминается. В режиме «Все» каждая заявка получает <strong>цвет своего владельца</strong>, а легенда называет людей, которые действительно есть на экране; при наведении на заявку видно, чья она, не отводя взгляда. Ничто ни от кого не скрыто &mdash; это те же заявки, которые уже перечислены во входящих.',
            'cal_edit' => '<strong>Перестановка работ.</strong> <strong>Перетащите заявку</strong> на другой день или время: в режиме «Месяц» время сохраняется, а в режимах «Неделя» и «День» берётся время, куда вы её опустили, с привязкой к ближайшей четверти часа. Длительность никогда не меняется &mdash; перетаскивание означает <em>начать тогда</em>, а не <em>сделать дольше</em>. Или <strong>нажмите на заявку</strong>, чтобы открыть её и изменить дату, время, длительность и настройку «весь день» либо полностью очистить расписание. Календарь также <strong>обновляется сам каждые несколько секунд</strong>, поэтому запланированное коллегой появляется без перезагрузки &mdash; но пока у вас открыта заявка или идёт перетаскивание, обновление ждёт.',
            'cal_month' => '<strong>Режим «Месяц»</strong> &mdash; классическая сетка из 6 строк с полосой заголовков дней недели; в ячейке каждого дня до трёх заявок с временем начала, плюс ссылка <em>+ ещё N</em>, которая открывает режим «День» для этой даты. Сегодняшний день выделен.',
            'cal_week' => '<strong>Режим «Неделя»</strong> &mdash; Пн&ndash;Вс вверху над 24-часовой вертикальной шкалой. Заявки отображаются на запланированную длительность, поэтому 15-минутная задача и многочасовая пересборка выглядят по-разному. Заявка на весь день лежит тонкой полосой вверху своего дня и не занимает весь столбец. Столбец сегодняшнего дня выделен; заголовок дней недели остаётся на месте, пока сетка часов прокручивается.',
            'cal_day' => '<strong>Режим «День»</strong> &mdash; один высокий столбец выбранного дня с той же 24-часовой шкалой. Заявки отображаются крупными блоками с <code>ticket_number &mdash; subject</code> и временем начала; нажмите на заявку, чтобы открыть подробности или изменить время её выполнения.',
            'rota_heading' => '<strong>График сотрудников</strong>',
            'rota_body' => 'Страница графика позволяет руководителям групп и менеджерам планировать смены аналитиков на неделю. Задавайте стандартные рабочие часы, назначайте периоды дежурства и отмечайте отпуска и отсутствия, чтобы команда всегда знала, кто доступен.',
            'rota_step1' => '<strong>Просмотрите сетку графика</strong> &mdash; график показывает аналитиков по одной оси и дни по другой, а блоки смен наглядно отображают покрытие.',
            'rota_step2' => '<strong>Добавляйте и изменяйте смены</strong> &mdash; нажмите на ячейку, чтобы назначить тип смены (например, Ранняя, Поздняя, Ночная, Дежурство). Изменения сохраняются сразу.',
            'rota_step3' => '<strong>Планируйте заранее</strong> &mdash; переходите вперёд по неделям, чтобы составлять график заблаговременно. Это обеспечивает достаточное покрытие в заведомо загруженные периоды, праздники и дни обучения.',
            'rota_step4' => '<strong>Заполняйте сразу несколько ячеек</strong> &mdash; нажмите <strong>правой кнопкой</strong> на ячейку и выберите <em>Копировать</em>, чтобы взять смену из неё, затем нажмите правой кнопкой на другую и выберите <em>Вставить</em>. Для нескольких ячеек <strong>протяните мышь по блоку</strong> (или щёлкайте по ячейкам по одной с нажатым Ctrl) и вставьте во все сразу. При наведении на <strong>заголовок дня</strong> подсвечивается весь день, а при наведении на <strong>имя аналитика</strong> &mdash; вся его неделя; нажмите правой кнопкой на любое из них и вставьте во всё. Если в части ячеек смена уже есть, меню предлагает оба способа простыми словами &mdash; <em>Вставить во все 7</em> и <em>Вставить в 6 пустых ячеек</em> &mdash; так что выбирать нужно до действия, а не после. Перезапись просит подтверждения и сообщает, сколько смен заменит; заполнение пропусков происходит сразу, ведь ничего не теряется. Те же меню также <strong>очищают</strong> день, неделю или выделенное, снова после сообщения, сколько смен будет удалено.',
            'rota_step5' => '<strong>Копирование целого дня или целой недели для одного человека</strong> &mdash; нажмите правой кнопкой на <strong>заголовок дня</strong> и выберите <em>Копировать</em>, чтобы взять все смены этого дня, либо на <strong>имя аналитика</strong>, чтобы взять всю его неделю. Вставка на другой день или другому аналитику приводит его в соответствие: смены, которых не было в копии, очищаются, так что вы получаете скопированный день, а не смесь двух. День можно вставить только на другой день, а аналитика &mdash; только на другого аналитика: день &mdash; это одна смена <em>на человека</em>, а неделя &mdash; одна смена <em>на день</em>, поэтому разумного способа наложить одно на другое нет. Попробуйте, и меню сообщит об этом и подскажет, куда можно вставить.',
            'rota_step6' => '<strong>Копирование целой недели</strong> &mdash; кнопки <strong>Копировать неделю</strong> и <strong>Вставить неделю</strong> вверху справа берут все смены просматриваемой недели и переносят на другую &mdash; это самый быстрый способ построить повторяющийся график. Вставка <em>заменяет</em> целевую неделю, поэтому подтверждение сообщает, сколько записей будет удалено. Затрагиваются только те дни и те люди, которые сетка действительно показывает.',
            'tip' => 'Используйте календарь и график вместе для эффективного планирования мощности. Если календарь показывает всплеск заявок каждый понедельник утром, добавьте на этот интервал дополнительное покрытие в графике.',
        ],
        'settings' => [
            'heading' => 'Настройки',
            'intro' => 'На странице «Настройки» вы настраиваете основные элементы системы заявок. Здесь управляются все справочные значения, цели SLA, импорт почты и пользовательские поля.',
            'sla_callout_title' => 'Управление SLA &mdash; полное руководство',
            'sla_callout_body' => 'Настраиваемые параметры, рабочие календари, статусы паузы, уведомления о нарушении, настройка задания cron, а также примеры для команд в одном и в разных часовых поясах. Тема достаточно объёмная, чтобы вынести её на отдельную страницу.',
            'card_dept_title' => 'Отделы',
            'card_dept_body' => 'Создайте отделы, например ИТ, кадры и финансы. Каждый отдел становится папкой во входящих и фильтром на панели',
            'card_types_title' => 'Типы заявок',
            'card_types_body' => 'Определите типы обращений, которые обрабатывает ваша служба: инцидент, запрос на обслуживание, проблема, изменение. Типы помогают аналитикам классифицировать работу',
            'card_priorities_title' => 'Приоритеты',
            'card_priorities_body' => 'Задайте уровни приоритета: названия, цвета и порядок сортировки. Каждый приоритет связан с целью SLA по реакции и решению',
            'card_statuses_title' => 'Статусы',
            'card_statuses_body' => 'Настройте этапы жизненного цикла заявки. По умолчанию есть статусы «Новая», «Открыта», «В работе», «Ожидает», «Решена» и «Закрыта»',
            'card_categories_title' => 'Категории',
            'card_categories_body' => 'Группируйте заявки по техническим областям: оборудование, ПО, сеть, доступ. Категории лежат в основе разбивки в отчётах',
            'card_sla_title' => 'Цели SLA',
            'card_sla_body' => 'Задайте целевое время реакции и решения для каждого приоритета. Таймеры SLA отображаются в заявках и запускают предупреждения о нарушении',
            'card_email_title' => 'Импорт писем',
            'card_email_body' => 'Подключите почтовый ящик (Exchange, Microsoft 365), чтобы письма автоматически импортировались как новые заявки. Ответы попадают в цепочку существующих заявок',
            'card_custom_title' => 'Пользовательские поля',
            'card_custom_body' => 'Добавляйте в заявки собственные поля для данных, которые нужны вашей организации и не входят в стандартный набор полей',
            'card_templates_title' => 'Шаблоны писем',
            'card_templates_body' => 'Настройте шаблоны уведомлений, которые отправляются конечным пользователям при создании, обновлении и решении заявок, а также для опроса CSAT. Вставляйте коды подстановки, например [requester_name] и [csat_link]',
            'card_checklists_title' => 'Чек-листы',
            'card_checklists_body' => 'Решите, что происходит, когда кто-то закрывает заявку, в которой остались невыполненные обязательные шаги чек-листа: <strong>предупредить</strong> и записать внутреннюю заметку с названиями шагов и именем закрывшего, или <strong>заблокировать</strong> закрытие, пока шаги не выполнены. Действует везде, где можно закрыть заявку, включая массовые действия, REST API и автоматизацию рабочих процессов',
            'card_custom_fields_title' => 'Пользовательские поля',
            'card_custom_fields_body' => 'Создайте дополнительные сведения, нужные для определённого вида заявок: текст, число, дату, да / нет, выпадающий список из ваших вариантов, веб-адрес или адрес эл. почты, и свяжите каждое поле с некоторыми типами заявок или со всеми. Для каждого поля выбирается, обязательно ли его заполнять <strong>при регистрации заявки</strong> (форма «Новая заявка», REST API и, при необходимости, портал), <strong>перед закрытием</strong> (по правилу «Обязательные поля») или в обоих случаях, а также <strong>спрашивать ли заявителя</strong> на портале - там появляется выбор типа заявки, как только он меняет набор вопросов. Ответы отображаются на панели свойств заявки и в её истории. При смене типа заявки ответы, которых нет у нового типа, скрываются, но не удаляются',
            'card_mandatory_title' => 'Обязательные поля',
            'card_mandatory_body' => 'Отметьте поля, которые должны быть заполнены до закрытия заявки: категория, код решения, владелец и так далее. Затем выберите, что происходит, если заявку закрывают с пустым полем: <strong>предупредить</strong>, <strong>предупредить и отправить письмо</strong> кому-то, например руководителю службы поддержки, или <strong>отказать</strong> в закрытии. Отдельный переключатель записывает это в заявку как внутреннюю заметку. Поле, отключённое для компании, никогда не считается обязательным, а объединение заявок никогда его не запускает. Действует везде, где можно закрыть заявку, включая массовые действия, REST API и автоматизацию рабочих процессов',
            'card_cleanup_title' => 'ИИ для очистки ответов',
            'card_cleanup_body' => 'Ключ Anthropic, модель и тон для кнопки ✨ «Очистка» в редакторе ответа. Ключ отделён от других функций ИИ для раздельного учёта расходов',
            'card_csat_title' => 'CSAT',
            'card_csat_body' => 'Режим отправки (выкл. / авто / вручную), задержка, защита «один опрос на заявку», шкала (звёзды или эмодзи). Полный процесс описан в разделе 6',
            'email_heading' => '<strong>Импорт писем подробно</strong>',
            'email_body' => 'Функция импорта писем подключается к вашему общему почтовому ящику и превращает новые сообщения в заявки. Когда конечный пользователь пишет на адрес поддержки (например, support@yourcompany.com), FreeITSM создаёт заявку: тема письма становится заголовком, а текст письма - описанием. Если отправитель отвечает на уведомление, ответ добавляется в существующую заявку, а не создаёт дубликат.',
            'email_step1' => '<strong>Настройте почтовый ящик</strong> &mdash; откройте «Настройки» и введите учётные данные Exchange или Microsoft 365. Для безопасного подключения без пароля поддерживается аутентификация OAuth.',
            'email_step2' => '<strong>Задайте интервал опроса</strong> &mdash; выберите, как часто FreeITSM проверяет почтовый ящик на новые сообщения. Чем короче интервал, тем быстрее создаются заявки.',
            'email_step3' => '<strong>Задайте значения по умолчанию</strong> &mdash; укажите отдел, тип и приоритет по умолчанию для заявок, созданных из писем. После импорта аналитики могут их изменить.',
            'tip' => 'Используйте шаблоны писем, чтобы поддерживать профессиональный и единый тон во всех сообщениях конечным пользователям. Шаблоны поддерживают динамические подстановки: номер заявки, имя заявителя, имя аналитика и статус.',
            'closemsg_heading' => '<strong>Разовое сообщение при закрытии заявки</strong>',
            'closemsg_body' => 'Добавьте <code>[ticket_closed_message]</code> в любое место активного шаблона <strong>Ticket closed</strong>, и с этого момента при переводе заявки в закрытый статус аналитику будет предложено ввести одну фразу - <em>&ldquo;запасное зарядное устройство лежит у вас на столе&rdquo;</em>, <em>&ldquo;закрываю, как договорились по телефону&rdquo;</em>. Введённый текст окажется ровно там, где вы поставили подстановку, так что формулировка вокруг неё остаётся под вашим контролем. Это не настройка, и нигде ничего не сохраняется: одна заметка, одна заявка, одно письмо. Если ничего не ввести, строки просто не будет - без пропуска и лишней пунктуации.',
            'closemsg_note' => '<strong>Запрос появляется, только если подстановка действительно есть в шаблоне.</strong> Без неё всё, что ввёл бы аналитик, молча пропадало бы, а в каждой службе, которой это не нужно, при каждом закрытии появлялся бы лишний щелчок. Поэтому функция включается, когда вы её настраиваете, и не мешает, когда не настроена.',
            'cat_heading' => '<strong>Категории и два соседних поля</strong>',
            'cat_body' => '<em>Тип</em> заявки говорит, что это за обращение, а <em>категория</em> - о чём оно. Составьте список в разделе <strong>Настройки &rarr; Категории</strong> вместе с переключателями, которые определяют, появляется ли что-либо из этого в заявке вообще.',
            'cat_card_one_title' => 'Категория',
            'cat_card_one_body' => 'Как заявка была описана при создании; выбирается, когда её регистрируют. У заявки ровно одна категория, поэтому отчёт по категориям всегда в сумме даёт реальное количество заявок.',
            'cat_card_close_title' => 'Категория при закрытии',
            'cat_card_close_body' => 'Тот же список, запрашиваемый ещё раз по завершении заявки. Обычно аналитик просто подтверждает выбор &mdash; смысл в тех случаях, когда первое предположение оказалось неверным: так вы узнаёте, что двенадцать из ваших тридцати семи «проблем с принтером» на самом деле были проблемами сети.',
            'cat_card_res_title' => 'Код решения',
            'cat_card_res_body' => 'Чем закончилась заявка, а не о чём она была &mdash; «Исправлено удалённо», «Проведено обучение», «Неисправность не найдена». Десять подходящих кодов уже есть с самого начала, и все их можно изменить.',
            'cat_rule_off' => '<strong>Все три изначально выключены.</strong> Сначала составьте список, затем включите нужные. Каждое можно настроить по-разному для каждой компании.',
            'cat_rule_levels' => 'У категорий могут быть подкатегории глубиной до трёх уровней, и ни один уровень не обязателен.',
            'cat_rule_type' => 'Категорию можно привязать к одному типу заявок, чтобы, например, «Оформление нового сотрудника» предлагалось только для запроса на обслуживание. Привязка относится к категории верхнего уровня, а её подкатегории следуют за ней.',
            'cat_rule_typechange' => '<strong>При смене типа заявки категория, принадлежавшая прежнему типу, сбрасывается</strong>, и об этом сообщается на экране. Категория, не привязанная ни к какому типу, сохраняется.',
            'cat_rule_portal' => 'Отметьте <em>Клиенты могут выбирать</em>, чтобы предложить категорию на портале самообслуживания. Заявители видят короткий список простыми словами, а аналитики - всё дерево.',
            'cat_rule_retire' => 'Выключите категорию, чтобы вывести её из употребления &mdash; она остаётся в заявках, где уже указана, но перестаёт предлагаться в новых. Это почти всегда лучше удаления, которое запрещено, пока категорию что-то использует.',
            'cat_rule_report' => 'Все три можно вывести на диаграммы панели заявок. Две диаграммы категорий суммируются до верхнего уровня, а заявки без значения учитываются как <em>Без категории</em>, а не скрываются.',
            'cat_tip' => 'Если не знаете, с чего начать, оставьте категории пустыми и включите только <strong>Код решения</strong>. Это поле быстрее всего меняет вашу работу &mdash; если пятая часть заявок закрывается с кодом «Проведено обучение», то это проблема документации, а не ИТ.',
        ],
        'tips' => [
            'heading' => 'Быстрые советы',
            'search_title' => 'Ищите по всему',
            'search_body' => 'Окно поиска проверяет номера заявок, темы, имена заявителей и адреса эл. почты. Используйте его, чтобы быстро найти связанные заявки, когда пользователь звонит по уже существующей проблеме.',
            'sla_title' => 'Следите за SLA',
            'sla_body' => 'Таймеры SLA видны в каждой заявке на панели чтения. Цветные индикаторы становятся жёлтыми при приближении нарушения и красными, когда цель пропущена, так что вы можете расставить приоритеты.',
            'reply_title' => 'Отвечайте из входящих',
            'reply_body' => 'Открывать почтовый клиент, чтобы ответить конечному пользователю, не нужно. Нажмите «Ответить» на панели чтения, чтобы отправить сообщение прямо отсюда. Оно автоматически попадёт в цепочку заявки.',
            'trail_title' => 'Используйте журнал действий',
            'trail_body' => 'Прежде чем взяться за заявку, прокрутите её журнал действий. Предыдущие заметки аналитиков, письма и изменения полей дают полный контекст, и вам не придётся просить пользователя повторять сведения.',
            'dash_title' => 'Панель для руководителей',
            'dash_body' => 'Соберите панель с виджетами: показатели соблюдения SLA, среднее время решения и заявки по отделам. Показывайте её на совещаниях команды, чтобы постоянно улучшать работу.',
            'rota_title' => 'Планируйте по графику',
            'rota_body' => 'Заполняйте график минимум за две недели вперёд. В сочетании с календарём он помогает заметить пробелы в покрытии до того, как они повлияют на время реакции.',
            'drag_title' => 'Перетаскивайте для сортировки',
            'drag_body' => 'Перетаскивайте заявки из списка на папки, чтобы обновить их, не открывая. Вложенные папки «отдел + статус» обновляют оба значения сразу. Раскрытие при наведении делает вложенные статусы доступными прямо во время перетаскивания.',
            'dbl_title' => 'Двойной щелчок для полного экрана',
            'dbl_body' => 'Одинарный щелчок показывает заявку на панели чтения, двойной открывает её на весь экран для сосредоточенной работы. Чтобы вернуться, нажмите значок увеличения рядом с темой.',
            'rightclick_title' => 'Правый щелчок для быстрых действий',
            'rightclick_body' => 'Щёлкните любую заявку правой кнопкой, чтобы одним щелчком сменить статус, приоритет или исполнителя, а также связать с CMDB и записать время - не отрываясь от заявки, которую вы читаете.',
            'ai_title' => 'Пусть ИИ приведёт ответ в порядок',
            'ai_body' => 'Наберите черновик (или просто пункты списком) и нажмите <strong>✨ Очистка</strong> &mdash; Claude перепишет его как полноценное письмо с приветствием, исправленной грамматикой и подписью. Ссылка «Отменить» доступна 30 секунд.',
            'feedback_title' => 'Просите отзывы',
            'feedback_body' => 'Включите CSAT в разделе <strong>Настройки &rarr; CSAT</strong>, чтобы заявители автоматически получали опрос после закрытия заявок. Тенденции по каждому аналитику находятся в <code>tickets/csat/</code> &mdash; настоящая находка для бесед о развитии.',
            'precreate_title' => 'Создавайте пользователей заранее',
            'precreate_body' => 'Кнопка <strong>Пользователи</strong> в навигации позволяет добавить пользователя до того, как ему понадобится создать заявку &mdash; оставьте пароль пустым, и он сможет сам получить учётную запись через портал самообслуживания.',
        ],
        'companies' => [
            'heading' => 'Компании и маршрутизация писем',
            'intro' => 'Если ваша установка обслуживает несколько компаний (например, ИТ-провайдер, поддерживающий нескольких клиентов), заявки каждой компании хранятся отдельно. В этом разделе объясняется, как входящее письмо находит нужную компанию.',
            'switcher_body' => 'В заголовке появляется <strong>переключатель компаний</strong>. Он задаёт компанию, в которой вы работаете &mdash; список заявок, папки и счётчики показывают только её, и любая созданная вами заявка относится к ней. Сотрудники с доступом к нескольким компаниям могут переключаться между ними; текущая компания всегда отображается, чтобы вы не ответили не в том контексте. Сами компании настраиваются в разделе <strong>Система &rarr; Компании</strong>.',
            'mailboxes_heading' => 'Каждый почтовый ящик относится к одному из двух видов &mdash; именно это определяет маршрутизацию:',
            'card_pinned_title' => 'Закреплённый ящик',
            'card_pinned_body' => 'Предназначен для одной компании (например, собственный <code>itsupport@</code> клиента). <strong>Вся</strong> его почта относится к этой компании &mdash; отправитель не учитывается &mdash; а ответы уходят с него же, так что клиент видит свою службу поддержки от начала и до конца.',
            'card_shared_title' => 'Общий приёмный ящик',
            'card_shared_body' => 'Один адрес для многих компаний (например, единый <code>support@theprovider.com</code> провайдера). По одному адресу он не может определить компанию, поэтому определяет её по тому, <strong>кто отправил письмо</strong>. Рекомендуемая схема для провайдера со многими клиентами.',
            'routing_heading' => 'Как общий приёмный ящик выбирает компанию',
            'routing_body' => 'Для каждого входящего письма он пробует следующие правила по порядку, и побеждает первое совпадение:',
            'flow_reply' => 'Ответ на заявку',
            'flow_sender' => 'Известный отправитель',
            'flow_domain' => 'Известный домен',
            'flow_triage' => 'Сортировка',
            'rule_reply' => '<strong>1. Ответ на существующую заявку</strong> &mdash; письмо распознаётся по номеру, присоединяется к этой заявке и сохраняет её компанию.',
            'rule_sender' => '<strong>2. Конкретный адрес отправителя</strong>, сопоставленный с компанией (например, <code>jane@gmail.com</code> &rarr; Acme) &mdash; эта компания. Проверяется раньше домена, поэтому работает даже для личных адресов и веб-почты.',
            'rule_domain' => '<strong>3. Домен отправителя</strong>, сопоставленный с компанией (например, любой адрес <code>@acme.com</code> &rarr; Acme) &mdash; эта компания.',
            'rule_triage' => '<strong>4. Совпадений нет</strong> &mdash; письмо попадает в очередь <strong>сортировки</strong>, а не теряется (см. ниже).',
            'keys_heading' => 'Домены и конкретные отправители (задаются для каждой компании в разделе Система &rarr; Компании)',
            'keys_body' => 'Это ключи, по которым сопоставляет общий приёмный ящик. Каждая компания перечисляет принадлежащие ей почтовые домены и, при желании, отдельные адреса отправителей.',
            'card_domains_title' => 'Почтовые домены',
            'card_domains_body' => 'Домены, которыми владеет компания (acme.com, acme.co.uk). Любой отправитель с зарегистрированного домена направляется в эту компанию. Домен принадлежит только одной компании.',
            'card_senders_title' => 'Конкретные отправители',
            'card_senders_body' => 'Отдельные адреса, сопоставленные с компанией и проверяемые раньше домена. Подходит для фрилансера или небольшого клиента, пишущего с личного адреса.',
            'card_public_title' => 'Публичные провайдеры',
            'card_public_body' => 'Gmail, Outlook, Yahoo и подобные нельзя сопоставить как домен (ими пользуется множество посторонних людей) &mdash; вместо этого сопоставьте точный адрес как конкретного отправителя.',
            'triage_heading' => 'Очередь сортировки &mdash; страховочная сетка',
            'triage_body' => 'Если письмо общего приёмного ящика не совпало ни с одной компанией, оно попадает в <strong>Сортировку</strong> (доступна из переключателя компаний, со счётчиком в реальном времени), а не теряется. Для каждого элемента показаны отправитель, домен, тема и ящик, на который письмо пришло. Отнести его к компании можно одним действием:',
            'triage_create' => 'Выберите существующую компанию или сразу создайте новую.',
            'triage_assign' => 'Для обычного домена при желании <strong>направьте этот домен</strong> в компанию; для публичного адреса или веб-почты при желании <strong>всегда относите этого отправителя</strong> к ней.',
            'triage_sweep' => 'Любой из вариантов <em>подхватывает остальное</em>: он переносит все остальные письма из очереди с этого домена или адреса и автоматически направляет будущую почту &mdash; так что каждого отправителя нужно разобрать только один раз.',
            'triage_tip' => 'Ничего не теряется. Неопознанная почта ждёт в сортировке, пока кто-нибудь её не распределит; нераспределённая заявка тем временем отображается в компании по умолчанию.',
            'test_heading' => 'Проверьте маршрутизацию до запуска',
            'test_body' => 'В разделе <strong>Система &rarr; Проверка маршрутизации писем</strong> можно сымитировать приход письма &mdash; выберите почтовый ящик, введите адрес отправителя &mdash; и увидеть, в какую компанию попадёт новая заявка (или что она уйдёт в сортировку) и какое правило это решило. Ничего не создаётся; просто читаются ваши настройки.',
            'settings_heading' => 'Настройки: общие по умолчанию, индивидуальные там, где это важно',
            'settings_body' => 'Некоторые из этих настроек можно <strong>настроить для каждой компании</strong>, а другие намеренно остаются общими. Если настройка - простой список вариантов, например <strong>типы заявок</strong> и <strong>источники</strong> &mdash; переключитесь в контекст компании, и вы увидите общие значения по умолчанию (у каждого есть значок глаза, чтобы скрыть неиспользуемые) и добавленные именно для неё. Нельзя скрыть или удалить вариант, пока его используют открытые заявки, а сами общие значения по умолчанию редактируются из MSP / компании по умолчанию.',
            'settings_custom_title' => 'Индивидуально для компании',
            'settings_custom_body' => 'Типы заявок и источники (уже сейчас), а также категории, SLA и рабочие часы (скоро) &mdash; то, что действительно отличается у разных клиентов.',
            'settings_global_title' => 'Общее для всех компаний',
            'settings_global_body' => 'Статусы и приоритеты везде одинаковы, поэтому межкомпанийная отчётность и SLA остаются согласованными; так же общие ваши команды, график и почтовые ящики &mdash; это ваша собственная работа, а не клиентская.',
