            'allview_card_scope_title' => 'Новых прав не даёт',
            'allview_card_scope_body' => '«Все» означает каждую компанию, к которой вы и так могли обратиться по одной. Аналитик, обслуживающий две из ваших трёх организаций, видит ровно эти две, а аналитик с одной компанией видит представление этой одной компании.',
            'allview_card_props_title' => 'Каждая организация остаётся отдельной',
            'allview_card_props_body' => 'Откройте заявку, и её тип, источник, категория и список решений будут принадлежать именно <em>этой</em> компании &mdash; поэтому категория, которая есть у одной организации и нет у другой, никогда не будет применена к чужой заявке.',
            'allview_card_new_title' => 'Новые заявки спрашивают о компании',
            'allview_card_new_body' => 'Единой активной компании, которую можно было бы предположить, нет, а выбор определяет номер заявки, ящик, с которого уходят ответы, и применяемый SLA. Список типов заполняется после выбора.',
            'allview_rule_chip' => 'Заявка, пришедшая по почте или с портала и ещё не направленная, помечается как <strong>Не направлена</strong>, а не отображается как «По умолчанию», чтобы выделяться для сортировки.',
            'allview_rule_reply' => 'Ответы по-прежнему уходят с того ящика, куда пришла заявка &mdash; это следует за заявкой, а не за представлением, поэтому общая доска не может отправить письмо с неверного адреса.',
            'allview_rule_knowledge' => 'Пока включено общее представление, <strong>Спросить ИИ</strong> ищет по всем компаниям, которые вы видите, а не по одной. Статьи, доступные всем компаниям, включаются в любом случае.',
            'allview_rule_trash' => '<strong>Очистка корзины никогда не охватывает несколько компаний.</strong> Она всегда применяется к единственной компании, которую вы выбрали последней, потому что «удалить всё в корзине» сразу в нескольких организациях - это не то, что кто-либо имеет в виду.',
            'allview_rule_other' => 'Расширяется только список заявок. Активы, изменения, задачи и CMDB по-прежнему показывают по одной компании &mdash; чтобы работать с ними, переключитесь на нужную компанию.',
            'privacy_heading' => 'Заявки каждой компании остаются закрытыми',
            'privacy_body' => 'Когда вы работаете в контексте компании, вы видите только заявки <strong>этой</strong> компании &mdash; в списке, в поиске, на панелях и в каждой открытой заявке (включая её письма, вложения, заметки и историю). Сотрудник может открыть заявку, только если ему дали доступ к её компании (компании каждого аналитика выбираются в разделе Система &rarr; Аналитики, а целой команде доступ выдаётся в разделе Система &rarr; Команды), поэтому случайно попасть к данным другого клиента невозможно. Это разделение обеспечивается везде за кулисами, а не только скрыто от глаз. В установке с одной компанией оно работает автоматически и незаметно &mdash; компания всего одна, и всё просто принадлежит ей.',
            'tip' => 'В установке с одной компанией ничего из этого не появляется &mdash; компания одна, все заявки принадлежат ей, а переключателя и сортировки нет. Эти функции включаются только после появления второй компании.',
