        'overview' => [
            'heading' => 'Обзор',
            'sub' => 'Что такое SLA, зачем они нужны и как в общих чертах работает механизм FreeITSM.',
            'p1' => 'Соглашение об уровне обслуживания (SLA) — это обещание о том, как быстро ваша команда отреагирует на заявку и решит её. FreeITSM отслеживает для каждой заявки два таймера: <strong>реакцию</strong> (время от создания заявки до первого действия аналитика) и <strong>решение</strong> (время от создания заявки до её закрытия). Обе цели задаются для каждого приоритета &mdash; например, у P1 может быть 30 минут на реакцию и 4 часа на решение, а у P4 — 8 рабочих часов и 5 рабочих дней.',
            'p2' => 'В механизме SLA в FreeITSM стоит понимать четыре проектных решения:',
            'choice_business' => '<strong>Рабочие часы, а не астрономическое время.</strong> Заявка P2, созданная в 16:30 с целью реакции в 1 час, не нарушает SLA в 17:30, если офис закрывается в 17:00. Таймер продолжится в 9:00 следующего рабочего дня. Это отраслевой стандарт и единственная честная модель, когда аналитики вечером уходят домой.',
            'choice_pause' => '<strong>Возможность паузы.</strong> Когда заявка находится в статусе с пометкой «Приостановить SLA» (например, <em>Ожидает ответа</em> или <em>Приостановлено</em>), таймер останавливается. Он продолжится, когда заявка вернётся в рабочий статус.',
            'choice_compute' => '<strong>Вычисление при просмотре, без хранения.</strong> Механизм заново вычисляет состояние SLA по журналу аудита заявки при каждом просмотре. Сохранённых счётчиков, которые могли бы разойтись с реальностью, нет. Если позже изменить часы рабочего календаря, SLA каждой прошлой заявки будет пересчитан по новым часам при следующем просмотре.',
            'choice_cutoff' => '<strong>Дата начала применения.</strong> Заданная администратором дата «Применять SLA с» гарантирует, что существующие заявки в системе не окажутся внезапно просроченными задним числом при включении SLA. Отслеживаются только заявки, созданные в эту дату или позже.',
            'tip' => 'Если вы новичок в ITIL: время реакции — это подтверждение (кто-то взял заявку в работу); время решения — это завершение (проблема пользователя устранена). Два таймера идут независимо и имеют разные цели.',
        ],
        'blocks' => [
            'heading' => 'Четыре составные части',
            'sub' => 'Настройте эти четыре вещи, и отслеживание SLA заработает. Всё остальное — необязательные улучшения.',
            'cal_heading' => '1. Рабочие календари',
            'cal_intro' => 'Календарь определяет, когда ваша служба поддержки открыта. У каждого календаря есть:',
            'cal_tz' => '<strong>Часовой пояс</strong> &mdash; идентификатор часового пояса IANA (напр. <code>Europe/London</code>, <code>America/New_York</code>, <code>Asia/Singapore</code>). Переходы на летнее время обрабатываются автоматически.',
            'cal_hours' => '<strong>Недельные рабочие часы</strong> &mdash; по одной строке на день недели с флажком «Открыто» и временем начала и окончания. Новые календари по умолчанию работают пн-пт 09:00-17:00, суббота и воскресенье закрыты. Строка без флажка «Открыто» означает, что в этот день служба закрыта.',
            'cal_holidays' => '<strong>Праздники</strong> &mdash; дата и необязательное название. Праздники переопределяют недельное расписание (служба закрыта, даже если праздник выпадает на понедельник).',
            'cal_default' => '<strong>Признак «по умолчанию»</strong> &mdash; ровно один календарь является календарём по умолчанию. Новые приоритеты наследуют его, если не указано иное.',
            'cal_outro' => 'Можно создать сколько угодно календарей &mdash; по одному на офис, на команду, один для VIP-клиентов с расширенными часами. Их используют цели SLA и механизм проверки нарушений.',
            'prio_heading' => '2. Приоритеты с целями SLA',
