            'prio_resolution' => '<strong>Цель по решению (минуты)</strong> &mdash; за какое время заявка должна быть закрыта.',
            'prio_calendar' => '<strong>Календарь</strong> &mdash; по какому рабочему календарю идёт таймер этого приоритета. Оставьте пустым, чтобы использовать календарь по умолчанию.',
            'prio_outro' => 'Если оставить оба поля целей пустыми, отслеживание SLA для этого приоритета полностью отключается &mdash; удобно для приоритетов «Информационный» или «Бэклог», где нет давления по времени.',
            'pause_heading' => '3. Статусы с паузой SLA',
            'pause_intro' => 'На вкладке «Статусы» есть отдельный столбец «Приостановить SLA». Отметьте в нём любой статус, в котором заявка ждёт чего-то вне контроля команды. Типичные кандидаты:',
            'pause_awaiting' => '<strong>Ожидает ответа</strong> &mdash; клиент должен предоставить нам информацию. Почти всегда признаётся справедливой паузой.',
            'pause_vendor' => '<strong>Приостановлено (поставщик)</strong> &mdash; ожидание ответа поддержки Microsoft или другого стороннего поставщика.',
            'pause_change' => '<strong>Приостановлено (окно изменений)</strong> &mdash; запланировано на будущее окно обслуживания.',
            'pause_parts' => '<strong>Приостановлено (запчасти)</strong> &mdash; ожидание поставки оборудования.',
            'pause_warn' => 'Универсальный статус «Приостановлено» можно использовать как лазейку для обхода SLA, когда заявка сложная или аналитик занят. Если в команде есть дисциплина, это нормально. Если нет, замените его более конкретными вариантами выше или опирайтесь на панель <strong>Watchtower</strong>, которая выделяет жёлтым заявки, стоящие на паузе более 24 часов.',
            'cutoff_heading' => '4. Дата начала применения (<code>Enforce SLAs from</code>)',
