        'behaviour' => [
            'heading' => 'Настройки поведения',
            'sub' => 'Они определяют, как механизм реагирует на особые случаи. Значения по умолчанию разумны &mdash; возвращаться к ним нужно только при особых предпочтениях.',
            'prio_heading' => 'Когда приоритет меняется по ходу работы',
