            'prio_forward' => '<strong>Вперёд (по умолчанию)</strong> &mdash; сохранить накопленные рабочие минуты и лишь сменить цель. Если заявка использовала 2 ч из 8 ч цели P3, теперь у неё 2 ч использовано против 1 ч цели P1 &mdash; то есть она уже нарушена. Это можно считать верным: проблема всё время была P1, просто команда этого не понимала.',
