            'recip_teams' => '<strong>Участники команд отдела заявки</strong> &mdash; все аналитики любой команды, связанной с отделом заявки. Охватывает всю очередь без ведения списка рассылки.',
            'recip_specific' => '<strong>Конкретный аналитик</strong> &mdash; схема «чемпион по SLA» или «менеджер сервиса», когда это конкретный человек, а не роль.',
            'recip_custom' => '<strong>Произвольные адреса эл. почты</strong> &mdash; свободный текст через запятую. Удобно для общих ящиков (<code>sla-alerts@company.com</code>), почтовых мостов в Slack/Teams или списков рассылки.',
            'tip' => 'Для каждой заявки отправляется не более одного письма на пару (цель, триггер) &mdash; фоновый обработчик cron фиксирует отправленное в таблице <code>sla_notifications_sent</code>. Предупреждение приходит один раз, нарушение — один раз, и всё &mdash; никаких циклов спама.',
            'warn' => '<strong>Нет правил — нет писем.</strong> Даже если все заявки в системе нарушены, ничего не отправится, пока вы не добавите хотя бы одно правило. Начните с пары правил с областью «По умолчанию»: Предупреждение и Нарушение, чтобы покрыть всё.',
        ],
        'cron' => [
            'heading' => 'Настройка задания cron',
            'sub' => 'Скрипт проверки нарушений нужно запускать по расписанию. Оптимально — раз в 5 минут.',
            'p1' => 'Индикаторы SLA в интерфейсе (метки во входящих, панели в области чтения) вычисляются на лету при загрузке страницы. Но письма о нарушениях могут уйти, только если <em>что-то</em> проактивно проверяет заявки, даже когда никто на них не смотрит. Это запланированное задание &mdash; в Windows планировщик заданий, в Linux cron.',
            'p2' => 'Скрипт называется <code>cron/sla_breach_check.php</code> и находится в каталоге установки FreeITSM. Запустить его можно двумя способами:',
            'cli_heading' => 'A. CLI (рекомендуется на сервере под вашим контролем)',
            'cli_note' => 'Аутентификация не требуется &mdash; кто может его запускать, определяют права доступа файловой системы.',
            'http_heading' => 'B. HTTP (для виртуального хостинга или внешних планировщиков)',
            'http_note' => 'Токен автоматически создаётся при первой установке и хранится в <code>system_settings</code> под ключом <code>sla_cron_token</code> (32 шестнадцатеричных символа, около 128 бит энтропии). Он хранится в зашифрованном виде, поэтому при прямом чтении строки вы увидите <code>ENC:…</code>, а не токен. Найти свой токен можно так:',
            'win_heading' => 'Планировщик заданий Windows',
            'win_intro' => 'Откройте планировщик заданий (<code>taskschd.msc</code>) и создайте новое задание с такими параметрами:',
            'tbl_field' => 'Поле',
            'tbl_value' => 'Значение',
            'win_r1_k' => 'Название',
            'win_r1_v' => 'FreeITSM &mdash; проверка нарушений SLA',
            'win_r2_k' => 'Выполнять вне зависимости от входа пользователя в систему',
            'win_r2_v' => 'Установите флажок',
            'win_r3_k' => 'Триггер',
            'win_r3_v' => 'Ежедневно, повторять каждый 1 день, повторять каждые 5 минут в течение 1 дня',
            'win_r4_k' => 'Действие',
            'win_r4_v' => 'Запуск программы',
            'win_r5_k' => 'Программа или сценарий',
            'win_r5_v' => '<code>C:\\wamp64\\bin\\php\\php8.2.x\\php.exe</code>',
            'win_r6_k' => 'Добавить аргументы',
            'win_r6_v' => '<code>C:\\wamp64\\www\\freeitsm-app\\cron\\sla_breach_check.php</code>',
            'win_r7_k' => 'Рабочая папка',
            'win_r7_v' => '<code>C:\\wamp64\\www\\freeitsm-app</code>',
            'linux_heading' => 'Cron в Linux',
            'linux_intro' => 'Добавьте одну строку в crontab (<code>crontab -e</code>):',
            'sec_heading' => 'Безопасность &mdash; что защищает конечную точку HTTP',
            'sec_intro' => 'Три уровня, все применяются автоматически:',
            'sec_token' => '<strong>1. Токен с общим секретом</strong> &mdash; случайные 128 бит на каждую установку, сравнение выполняется за постоянное время для защиты от атак по времени.',
            'sec_lockout' => '<strong>2. Блокировка по IP после неудачной аутентификации</strong> &mdash; более 10 попыток с неверным токеном с одного IP за последний час вызывают часовую блокировку с ответом 429. Защищает от подбора без fail2ban.',
            'sec_interval' => '<strong>3. Минимальный интервал между успешными запусками</strong> &mdash; <code>sla_cron_min_interval_seconds</code> (по умолчанию 30 с). Даже запрос с верным токеном получит 429, если придёт раньше этого срока после последнего успешного запуска. Защищает от случайного двойного планирования и бесконечных циклов.',
            'log_heading' => 'Журнал активности',
            'log_body' => 'Каждый вызов (принятый или отклонённый) записывается в таблицу <code>sla_cron_runs</code> со временем, результатом, счётчиками и IP клиента. Последние 20 запусков можно посмотреть в панели <strong>Активность cron</strong> внизу вкладки настроек SLA &mdash; это удобно, чтобы проверить, что расписание работает, и разобрать неудачные попытки аутентификации. Строки автоматически удаляются через <code>sla_cron_log_retention_days</code> (по умолчанию 30), поэтому таблица остаётся небольшой.',
        ],
        'examples' => [
            'heading' => 'Примеры',
            'sub' => 'От простого случая с одним часовым поясом до более сложного межчасового, где нужно определить, что такое «справедливо».',
            'ex1_heading' => 'Пример 1: заявка создана в Великобритании, служба поддержки в Великобритании',
            'ex1_title' => 'Простой случай',
            'ex1_tag' => 'один часовой пояс',
            'ex1_setup' => '<strong>Настройка:</strong> один рабочий календарь <em>UK Office</em> с часовым поясом <code>Europe/London</code>, пн-пт 09:00-17:00, без праздников. У приоритета P2 цель реакции 1 час и цель решения 4 часа, обе по календарю <em>UK Office</em>.',
            'ex1_scenario' => '<strong>Сценарий:</strong> пользователь создаёт заявку P2 в <strong>16:30 по Великобритании в среду</strong>.',
            'ex1_timeline' => 'Ср 16:30 UK &mdash; <strong>заявка создана</strong>, таймер реакции запущен.
Ср 17:00 UK &mdash; офис закрывается, таймер на паузе (использовано 30 мин из 60 мин цели).
Чт 09:00 UK &mdash; офис открывается, таймер продолжается.
Чт 09:30 UK &mdash; аналитик отвечает. SLA по реакции выполнен впритык (использовано 60 мин, цель 60 мин).',
            'ex1_outro' => 'Если бы аналитик не ответил до <strong>четверга 10:00 UK</strong>, реакция была бы <strong>нарушена на 30 минут</strong> (использовано 90 мин при цели 60 мин &mdash; 30 в среду вечером, 60 в четверг утром). Часовой таймер идёт только в рабочие часы, но заявка в конце дня всё равно съедает большую часть своего бюджета на ночь, когда офис снова открывается &mdash; аналитик, пришедший в 09:00, легко решит, что у него есть целый час, хотя на самом деле осталось только 30 минут.',
            'ex2_heading' => 'Пример 2: заявка создана в Великобритании, служба поддержки в Эстонии',
            'ex2_title' => 'Случай с разными часовыми поясами',
            'ex2_tag' => '3 способа определить «справедливо»',
            'ex2_setup' => '<strong>Настройка:</strong> клиенты из Великобритании (<code>Europe/London</code>, GMT/BST), служба поддержки в Эстонии (<code>Europe/Tallinn</code>, EET/EEST &mdash; <strong>на 2 часа впереди Великобритании</strong>). Обе службы номинально работают с 09:00 до 17:00 по местному времени.',
            'ex2_scenario' => '<strong>Сценарий:</strong> британский клиент создаёт заявку P2 в <strong>16:30 по Великобритании в пятницу</strong> (= 18:30 в Эстонии, после закрытия эстонского офиса). Следующая возможность для эстонского аналитика заняться ею — понедельник 09:00 по Эстонии (= 07:00 по Великобритании). Цель реакции — 1 час.',
            'ex2_question' => 'Что должен показывать SLA? Есть три допустимых ответа, и каждый справедлив по-своему. Какой календарь назначить приоритету, вы выбираете исходя из того, что обещает ваш договор об обслуживании.',
            'optA_label' => 'Вариант A &mdash; в интересах клиента',
            'optA_p1' => '<strong>Назначьте приоритету календарь с <em>британскими</em> часами.</strong> Таймер идёт по британским 09:00-17:00 независимо от того, где находится аналитик.',
            'optA_p2' => 'В описанном сценарии заявка создана в 16:30 UK в пятницу: таймер идёт 16:30&ndash;17:00 UK в пятницу (использовано 30 мин), на ночь и выходные ставится на паузу, продолжается в понедельник в 09:00 UK. Если эстонский аналитик ответит в понедельник в 10:00 по Эстонии (= 08:00 UK), британский календарь всё ещё на паузе (британский офис открывается в 09:00 UK), поэтому дополнительные минуты не набегают &mdash; использовано остаётся 30 мин. <strong>SLA выполнен с запасом в 30 мин</strong>. Любой ответ после 09:30 UK (= 11:30 по Эстонии) будет нарушением.',
            'optA_p3' => '<em>Справедливо для:</em> клиента. Его опыт соответствует его рабочему дню.<br><em>Компромисс:</em> эстонские аналитики должны быть доступны с 09:00 до 17:00 по британскому времени (= 11:00-19:00 по Эстонии), что удлиняет их рабочий день на 2 часа.',
            'optB_label' => 'Вариант B &mdash; в интересах аналитика',
            'optB_p1' => '<strong>Назначьте приоритету календарь с <em>эстонскими</em> часами.</strong> Таймер идёт по эстонским 09:00-17:00.',
            'optB_p2' => 'Тот же сценарий: заявка создана в 18:30 по Эстонии в пятницу (после закрытия), таймер стоит все выходные и начинает идти в понедельник в 09:00 по Эстонии (= 07:00 UK). Если аналитик ответит в понедельник в 09:30 по Эстонии (= 07:30 UK), SLA по реакции израсходует 30 мин из 60 мин цели &mdash; <strong>выполнен с запасом в 30 мин</strong>. Британский клиент создал заявку в 16:30 UK в пятницу и получил ответ в 07:30 UK в понедельник &mdash; его реальное ожидание было намного дольше, чем показывает SLA.',
            'optB_p3' => '<em>Справедливо для:</em> аналитиков. Они работают в обычные часы.<br><em>Компромисс:</em> британским клиентам может казаться, что SLA «лжёт», если заявка, созданная в пятницу днём, не подтверждена до утра понедельника по Эстонии, а отчёт говорит, что SLA по реакции составил 1 час. Убедитесь, что в договоре об обслуживании прямо сказано, что SLA считается по часам работы службы поддержки.',
            'optC_label' => 'Вариант C &mdash; окно пересечения (самый строгий)',
            'optC_p1' => '<strong>Назначьте приоритету календарь, охватывающий только часы, когда открыты обе службы.</strong> Британские 09:00-17:00 пересекаются с эстонскими 09:00-17:00 (= UK 07:00-15:00) в <strong>окне UK 09:00-15:00</strong> &mdash; 6 часов в рабочий день.',
            'optC_p2' => 'Тот же сценарий: заявка создана в 16:30 UK в пятницу (вне пересечения, так как оно закрывается в 15:00 UK), таймер стоит все выходные и продолжается в понедельник в 09:00 UK (= 11:00 по Эстонии, когда пересечение снова открывается). Если эстонский аналитик ответит в 11:30 по Эстонии (= 09:30 UK), SLA по реакции израсходует 30 мин из 60 мин цели &mdash; <strong>выполнен с запасом в 30 мин</strong>. Ответ дан во время окна пересечения, поэтому засчитывается сразу.',
            'optC_p3' => '<em>Справедливо для:</em> обеих сторон &mdash; SLA идёт только в часы, когда служба действительно может продвинуть заявку И клиент находится на рабочем месте, чтобы получить ответ.<br><em>Компромисс:</em> более короткое дневное окно означает более долгое реальное время для достижения жёстких целей. Цель решения в 4 часа занимает 1,5 дня пересечения, тогда как при обычном 8-часовом календаре она уложилась бы в один день.',
            'choose_tip' => '<strong>Как выбрать:</strong> посмотрите на договор об обслуживании. Если в нём сказано «реакция в течение 1 часа с момента получения» &mdash; это вариант A (часы клиента). Если «реакция в течение 1 рабочего часа» &mdash; обычно это вариант B (по часам той службы, которая работает). Если «в течение 1 часа совместной доступности» &mdash; это вариант C. Если договора нет, спросите команду: хотите ли вы чувствовать давление вне эстонских часов (вариант A) или хотите, чтобы британские клиенты иногда чувствовали себя проигнорированными (вариант B)?',
            'ex3_heading' => 'Пример 3: пауза таймера при ожидании поставщика',
            'ex3_title' => 'Как статусы с паузой работают на практике',
            'ex3_tag' => 'пауза таймера',
            'ex3_setup' => '<strong>Настройка:</strong> приоритет P3 с целью решения 8 рабочих часов, календарь UK, статус «Ожидает поставщика» с пометкой <em>Приостановить SLA</em>.',
            'ex3_scenario' => '<strong>Сценарий:</strong> заявка создана в пн 09:00 UK. Аналитик эскалирует её в Microsoft в пн 11:00 UK и переводит заявку в статус «Ожидает поставщика». Microsoft отвечает в ср 14:00 UK. Аналитик внедряет исправление и закрывает заявку в чт 10:00 UK.',
            'ex3_timeline' => 'Пн 09:00 &mdash; заявка создана, таймер решения идёт.
Пн 11:00 &mdash; переведена в «Ожидает поставщика», <strong>таймер на паузе</strong> (использовано 2 ч).
Ср 14:00 &mdash; возвращена в «В работе», <strong>таймер продолжается</strong>.
Ср 17:00 &mdash; офис закрывается (всего использовано 5 ч).
Чт 09:00 &mdash; офис открывается.
Чт 10:00 &mdash; заявка закрыта (всего использовано 6 ч). <strong>SLA выполнен</strong> при цели 8 ч.',
            'ex3_outro' => 'Реально прошло: около 3 дней. Время SLA: 6 рабочих часов. Без пометки паузы статуса SLA учёл бы все 2 дня ожидания поставщика плюс рабочие часы, всего около 18 рабочих часов &mdash; значительное нарушение.',
        ],
